    "func home(): str {\n"
    "    if isWindows() {\n"
    "        return envOr(\"USERPROFILE\", \"\");\n"
    "    }\n"
    "    return envOr(\"HOME\", \"\");\n"
    "}\n"
    "\n"
    "// A directory for temporary files.\n"
    "func tempDir(): str {\n"
    "    if isWindows() {\n"
    "        return envOr(\"TEMP\", \".\");\n"
    "    }\n"
    "    return envOr(\"TMPDIR\", \"/tmp\");\n"
    "}\n"
    "\n";

static const char src_time[] =
    "// The `time` module: the clock. Ambient authority, so only the standard\n"
    "// interpreter opens it; a sandboxed host registers its own clock if needed.\n"
    "\n"
    "import strings;\n"
    "\n"
    "// Milliseconds since the Unix epoch, UTC.\n"
    "extern func nowMs(): int;\n"
    "\n"
    "// Milliseconds since the interpreter started. Use this for measuring\n"
    "// durations; it does not jump when the system clock is corrected.\n"
    "extern func monoMs(): int;\n"
    "\n"
    "extern func sleepMs(ms: int);\n"
    "\n"
    "// The current time as ISO 8601 in UTC, \"2026-10-04T18:33:07Z\".\n"
    "extern func iso(): str;\n"
    "\n"
    "func nowSec(): int {\n"
    "    return nowMs() / 1000;\n"
    "}\n"
    "\n"
    "// Today as \"2026-10-04\".\n"
    "func today(): str {\n"
    "    return strings.sub(iso(), 0, 10);\n"
    "}\n"
    "\n";

static const char src_rand[] =
    "// The `rand` module: pseudo-random numbers. xorshift64*, seeded from the\n"
    "// clock, reproducible once `seed` is called. Not cryptographic. Only the\n"
    "// standard interpreter opens this.\n"
    "\n"
    "import strings;\n"
    "\n"
    "// Fixes the sequence. Zero is replaced, because it is a fixed point of the\n"
    "// generator rather than a seed.\n"
    "extern func seed(n: int);\n"
    "\n"
    "// A number in 0 ..< n, uniformly. Zero when `n` is not positive.\n"
    "extern func below(n: int): int;\n"
    "\n"
    "// A float in 0.0 ..< 1.0.\n"
    "extern func real(): float;\n"
    "\n"
    "// A number in lo ..< hi, or `lo` if that range is empty.\n"
    "func between(lo: int, hi: int): int {\n"
    "    if hi <= lo {\n"
    "        return lo;\n"
    "    }\n"
    "    return lo + below(hi - lo);\n"
    "}\n"
    "\n"
    "// True with probability `p`.\n"
    "func chance(p: float): bool {\n"
    "    return real() < p;\n"
    "}\n"
    "\n"
    "// A float in lo ..< hi.\n"
    "func realBetween(lo: float, hi: float): float {\n"
    "    return lo + real() * (hi - lo);\n"
    "}\n"
    "\n"
    "// A valid index into an array of `count` items, or -1 when it is empty.\n"
    "func index(count: int): int {\n"
    "    if count <= 0 {\n"
    "        return 0 - 1;\n"
    "    }\n"
    "    return below(count);\n"
    "}\n"
    "\n"
    "// A random element, or `fallback` for an empty array.\n"
    "func pick[T](xs: [T], fallback: T): T {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    return xs[below(len(xs))];\n"
    "}\n"
    "\n"
    "// Shuffles the array in place (Fisher-Yates).\n"
    "func shuffle[T](xs: [T]) {\n"
    "    var i = len(xs) - 1;\n"
    "    while i > 0 {\n"
    "        let j = below(i + 1);\n"
    "        let tmp = xs[i];\n"
    "        xs[i] = xs[j];\n"
    "        xs[j] = tmp;\n"
    "        i -= 1;\n"
    "    }\n"
    "}\n"
    "\n"
    "// A random version 4 UUID such as \"3f2b8c1e-9d4a-4b6f-8a1c-5e7d2f9a0b34\".\n"
    "// Not cryptographically secure, like everything in this module.\n"
    "func uuid(): str {\n"
    "    let digits = \"0123456789abcdef\";\n"
    "    var out = \"\";\n"
    "    var i = 0;\n"
    "    while i < 36 {\n"
    "        if i == 8 || i == 13 || i == 18 || i == 23 {\n"
    "            out = out + \"-\";\n"
    "        } else if i == 14 {\n"
    "            out = out + \"4\";\n"
    "        } else if i == 19 {\n"
    "            let v = 8 + below(4);\n"
    "            out = out + strings.sub(digits, v, v + 1);\n"
    "        } else {\n"
    "            let v = below(16);\n"
    "            out = out + strings.sub(digits, v, v + 1);\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n";

