static const char src_json[] =
    "// The `json` module: parse JSON text into a `Json` value and write one back.\n"
    "//\n"
    "//     switch json.parse(\"{\\\"hp\\\": 10}\") {\n"
    "//         case Success(v): print(\"${json.getInt(v, \"hp\", 0)}\");\n"
    "//         case Failure(msg): print(msg);\n"
    "//     }\n"
    "//\n"
    "// A `Json` is one of the six JSON shapes. Numbers are all floats, as in JSON\n"
    "// itself; `asInt` and `getInt` round them for you. Object keys keep the order\n"
    "// they were written in. A key that appears twice keeps its last value.\n"
    "//\n"
    "// The accessors never fail: asking an array for a key, or a missing key for a\n"
    "// string, gives the fallback (or `Null`), so a chain of `get` calls into\n"
    "// data of an unexpected shape ends in a default instead of an error.\n"
    "\n"
    "import result;\n"
    "import strings;\n"
    "import math;\n"
    "\n"
    "enum Json {\n"
    "    Null,\n"
    "    Bool(value: bool),\n"
    "    Num(value: float),\n"
    "    Str(value: str),\n"
    "    Arr(items: [Json]),\n"
    "    Obj(fields: {str: Json}),\n"
    "}\n"
    "\n"
    "// --- building ----------------------------------------------------------------\n"
    "\n"
    "func fromInt(n: int): Json {\n"
    "    return Json.Num(math.toFloat(n));\n"
    "}\n"
    "\n"
    "func emptyArray(): Json {\n"
    "    var items: [Json] = [];\n"
    "    return Json.Arr(items);\n"
    "}\n"
    "\n"
    "func emptyObject(): Json {\n"
    "    var fields: {str: Json} = {};\n"
    "    return Json.Obj(fields);\n"
    "}\n"
    "\n"
    "// --- reading -----------------------------------------------------------------\n"
    "\n"
    "func isNull(v: Json): bool {\n"
    "    switch v {\n"
    "        case Null: return true;\n"
    "        case Bool(b): return false;\n"
    "        case Num(n): return false;\n"
    "        case Str(s): return false;\n"
    "        case Arr(items): return false;\n"
    "        case Obj(fields): return false;\n"
    "    }\n"
    "}\n"
    "\n"
    "// The value under `key` in an object, or Null if `v` is not an object or has\n"
    "// no such key.\n"
    "func get(v: Json, key: str): Json {\n"
    "    switch v {\n"
    "        case Obj(fields): {\n"
    "            if contains(fields, key) {\n"
    "                return fields[key];\n"
    "            }\n"
    "            return Json.Null;\n"
    "        }\n"
    "        case Null: return Json.Null;\n"
    "        case Bool(b): return Json.Null;\n"
    "        case Num(n): return Json.Null;\n"
    "        case Str(s): return Json.Null;\n"
    "        case Arr(list): return Json.Null;\n"
    "    }\n"
    "}\n"
    "\n"
    "// The i'th element of an array, or Null when out of range or not an array.\n"
    "func at(v: Json, i: int): Json {\n"
    "    switch v {\n"
    "        case Arr(items): {\n"
    "            if i < 0 || i >= len(items) {\n"
    "                return Json.Null;\n"
    "            }\n"
    "            return items[i];\n"
    "        }\n"
    "        case Null: return Json.Null;\n"
    "        case Bool(b): return Json.Null;\n"
    "        case Num(n): return Json.Null;\n"
    "        case Str(s): return Json.Null;\n"
    "        case Obj(fields): return Json.Null;\n"
    "    }\n"
    "}\n"
    "\n"
    "// Elements of an array, keys of an object, otherwise zero.\n"
    "func size(v: Json): int {\n"
    "    switch v {\n"
    "        case Arr(items): return len(items);\n"
    "        case Obj(fields): return len(fields);\n"
    "        case Null: return 0;\n"
    "        case Bool(b): return 0;\n"
    "        case Num(n): return 0;\n"
    "        case Str(s): return 0;\n"
    "    }\n"
    "}\n"
    "\n"
    "func has(v: Json, key: str): bool {\n"
    "    switch v {\n"
    "        case Obj(fields): return contains(fields, key);\n"
    "        case Null: return false;\n"
    "        case Bool(b): return false;\n"
    "        case Num(n): return false;\n"
    "        case Str(s): return false;\n"
    "        case Arr(list): return false;\n"
    "    }\n"
    "}\n"
    "\n"
    "// The keys of an object in order; empty for anything else.\n"
    "func keysOf(v: Json): [str] {\n"
    "    var out: [str] = [];\n"
    "    switch v {\n"
    "        case Obj(fields): {\n"
    "            for k in keys(fields) {\n"
    "                push(out, k);\n"
    "            }\n"
    "        }\n"
    "        case Null: {}\n"
    "        case Bool(b): {}\n"
    "        case Num(n): {}\n"
    "        case Str(s): {}\n"
    "        case Arr(list): {}\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// The elements of an array; empty for anything else.\n"
    "func items(v: Json): [Json] {\n"
    "    var out: [Json] = [];\n"
    "    switch v {\n"
    "        case Arr(list): {\n"
    "            for x in list {\n"
    "                push(out, x);\n"
    "            }\n"
    "        }\n"
    "        case Null: {}\n"
    "        case Bool(b): {}\n"
    "        case Num(n): {}\n"
    "        case Str(s): {}\n"
    "        case Obj(fields): {}\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func asStr(v: Json, fallback: str): str {\n"
    "    switch v {\n"
    "        case Str(s): return s;\n"
    "        case Null: return fallback;\n"
    "        case Bool(b): return fallback;\n"
    "        case Num(n): return fallback;\n"
    "        case Arr(list): return fallback;\n"
    "        case Obj(fields): return fallback;\n"
    "    }\n"
    "}\n"
    "\n"
    "func asFloat(v: Json, fallback: float): float {\n"
    "    switch v {\n"
    "        case Num(n): return n;\n"
    "        case Null: return fallback;\n"
    "        case Bool(b): return fallback;\n"
    "        case Str(s): return fallback;\n"
    "        case Arr(list): return fallback;\n"
    "        case Obj(fields): return fallback;\n"
    "    }\n"
    "}\n"
    "\n"
    "// A number rounded to the nearest int, or `fallback` for anything else.\n"
    "func asInt(v: Json, fallback: int): int {\n"
    "    switch v {\n"
    "        case Num(n): return math.round(n);\n"
    "        case Null: return fallback;\n"
    "        case Bool(b): return fallback;\n"
    "        case Str(s): return fallback;\n"
    "        case Arr(list): return fallback;\n"
    "        case Obj(fields): return fallback;\n"
    "    }\n"
    "}\n"
    "\n"
    "func asBool(v: Json, fallback: bool): bool {\n"
    "    switch v {\n"
    "        case Bool(b): return b;\n"
    "        case Null: return fallback;\n"
    "        case Num(n): return fallback;\n"
    "        case Str(s): return fallback;\n"
    "        case Arr(list): return fallback;\n"
    "        case Obj(fields): return fallback;\n"
    "    }\n"
    "}\n"
    "\n"
    "// `get` and `asX` in one step.\n"
    "func getStr(v: Json, key: str, fallback: str): str {\n"
    "    return asStr(get(v, key), fallback);\n"
    "}\n"
    "\n"
    "func getInt(v: Json, key: str, fallback: int): int {\n"
    "    return asInt(get(v, key), fallback);\n"
    "}\n"
    "\n"
    "func getFloat(v: Json, key: str, fallback: float): float {\n"
    "    return asFloat(get(v, key), fallback);\n"
    "}\n"
    "\n"
    "func getBool(v: Json, key: str, fallback: bool): bool {\n"
    "    return asBool(get(v, key), fallback);\n"
    "}\n"
    "\n"
    "// --- writing -----------------------------------------------------------------\n"
    "\n"
    "func hexDigit(n: int): str {\n"
    "    return strings.sub(\"0123456789abcdef\", n, n + 1);\n"
    "}\n"
    "\n"
    "// `s` as a JSON string literal, quotes included.\n"
    "func quote(s: str): str {\n"
    "    var out: [str] = [\"\\\"\"];\n"
    "    for c in strings.chars(s) {\n"
    "        let code = strings.code(c);\n"
    "        if c == \"\\\"\" {\n"
    "            push(out, \"\\\\\\\"\");\n"
    "        } else if c == \"\\\\\" {\n"
    "            push(out, \"\\\\\\\\\");\n"
    "        } else if c == \"\\n\" {\n"
    "            push(out, \"\\\\n\");\n"
    "        } else if c == \"\\r\" {\n"
    "            push(out, \"\\\\r\");\n"
    "        } else if c == \"\\t\" {\n"
    "            push(out, \"\\\\t\");\n"
    "        } else if code == 8 {\n"
    "            push(out, \"\\\\b\");\n"
    "        } else if code == 12 {\n"
    "            push(out, \"\\\\f\");\n"
    "        } else if code < 32 {\n"
    "            push(out, \"\\\\u00\" + hexDigit(code / 16) + hexDigit(code % 16));\n"
    "        } else {\n"
    "            push(out, c);\n"
    "        }\n"
    "    }\n"
    "    push(out, \"\\\"\");\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "func numberText(n: float): str {\n"
    "    // NaN and the infinities have no JSON spelling.\n"
    "    if n != n || n > 1.0e300 || n < -1.0e300 {\n"
    "        return \"null\";\n"
    "    }\n"
    "    if n == math.toFloat(math.floor(n)) && math.abs(n) < 1.0e15 {\n"
    "        return strings.fromInt(math.toInt(n));\n"
    "    }\n"
    "    return strings.fromFloat(n);\n"
    "}\n"
    "\n"
    "func write(v: Json, out: [str], indent: int, level: int) {\n"
    "    switch v {\n"
    "        case Null: push(out, \"null\");\n"
    "        case Bool(b): push(out, strings.fromBool(b));\n"
    "        case Num(n): push(out, numberText(n));\n"
    "        case Str(s): push(out, quote(s));\n"
    "        case Arr(list): {\n"
    "            if len(list) == 0 {\n"
    "                push(out, \"[]\");\n"
    "                return;\n"
    "            }\n"
    "            push(out, \"[\");\n"
    "            var first = true;\n"
    "            for x in list {\n"
    "                if !first {\n"
    "                    push(out, \",\");\n"
    "                }\n"
    "                first = false;\n"
    "                newline(out, indent, level + 1);\n"
    "                write(x, out, indent, level + 1);\n"
    "            }\n"
    "            newline(out, indent, level);\n"
    "            push(out, \"]\");\n"
    "        }\n"
    "        case Obj(fields): {\n"
    "            if len(fields) == 0 {\n"
    "                push(out, \"{}\");\n"
    "                return;\n"
    "            }\n"
    "            push(out, \"{\");\n"
    "            var first = true;\n"
    "            for k in keys(fields) {\n"
    "                if !first {\n"
    "                    push(out, \",\");\n"
    "                }\n"
    "                first = false;\n"
    "                newline(out, indent, level + 1);\n"
    "                push(out, quote(k));\n"
    "                if indent > 0 {\n"
    "                    push(out, \": \");\n"
    "                } else {\n"
    "                    push(out, \":\");\n"
    "                }\n"
    "                write(fields[k], out, indent, level + 1);\n"
    "            }\n"
    "            newline(out, indent, level);\n"
    "            push(out, \"}\");\n"
    "        }\n"
    "    }\n"
    "}\n"
    "\n"
    "func newline(out: [str], indent: int, level: int) {\n"
    "    if indent > 0 {\n"
    "        push(out, \"\\n\" + strings.repeat(\" \", indent * level));\n"
    "    }\n"
    "}\n"
    "\n"
    "// Compact text with no spaces.\n"
    "func stringify(v: Json): str {\n"
    "    var out: [str] = [];\n"
    "    write(v, out, 0, 0);\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "// Indented text, `indent` spaces per level.\n"
    "func pretty(v: Json, indent: int): str {\n"
    "    var out: [str] = [];\n"
    "    write(v, out, indent, 0);\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "// --- parsing -----------------------------------------------------------------\n"
    "\n"
    "struct Reader {\n"
    "    chars: [str];\n"
    "    pos: int;\n"
    "    error: str;\n"
    "}\n"
    "\n"
    "func fail(r: Reader, message: str) {\n"
    "    if !strings.isEmpty(r.error) {\n"
    "        return;\n"
    "    }\n"
    "    var line = 1;\n"
    "    var col = 1;\n"
    "    var i = 0;\n"
    "    while i < r.pos && i < len(r.chars) {\n"
    "        if r.chars[i] == \"\\n\" {\n"
    "            line += 1;\n"
    "            col = 1;\n"
    "        } else {\n"
    "            col += 1;\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    r.error = \"${message} at line ${line}, column ${col}\";\n"
    "}\n"
    "\n"
    "func peek(r: Reader): str {\n"
    "    if r.pos >= len(r.chars) {\n"
    "        return \"\";\n"
    "    }\n"
    "    return r.chars[r.pos];\n"
    "}\n"
    "\n"
    "func skipSpace(r: Reader) {\n"
    "    while r.pos < len(r.chars) {\n"
    "        let c = r.chars[r.pos];\n"
    "        if c == \" \" || c == \"\\n\" || c == \"\\r\" || c == \"\\t\" {\n"
    "            r.pos += 1;\n"
    "        } else {\n"
    "            return;\n"
    "        }\n"
    "    }\n"
    "}\n"
    "\n"
    "func isDigit(c: str): bool {\n"
    "    return strings.len(c) == 1 && strings.contains(\"0123456789\", c);\n"
    "}\n"
    "\n"
    "func hexValue(c: str): int {\n"
    "    if strings.len(c) != 1 {\n"
    "        return -1;\n"
    "    }\n"
    "    return strings.indexOf(\"0123456789abcdef\", strings.lower(c));\n"
    "}\n"
    "\n"
    "// Four hex digits at the cursor, or -1.\n"
    "func hex4(r: Reader): int {\n"
    "    var v = 0;\n"
    "    var i = 0;\n"
    "    while i < 4 {\n"
    "        if r.pos >= len(r.chars) {\n"
    "            return -1;\n"
    "        }\n"
    "        let d = hexValue(r.chars[r.pos]);\n"
    "        if d < 0 {\n"
    "            return -1;\n"
    "        }\n"
    "        v = v * 16 + d;\n"
    "        r.pos += 1;\n"
    "        i += 1;\n"
    "    }\n"
    "    return v;\n"
    "}\n"
    "\n"
    "func parseString(r: Reader): str {\n"
    "    r.pos += 1;\n"
    "    var parts: [str] = [];\n"
    "    while true {\n"
    "        if r.pos >= len(r.chars) {\n"
    "            fail(r, \"unterminated string\");\n"
    "            return \"\";\n"
    "        }\n"
    "        let c = r.chars[r.pos];\n"
    "        r.pos += 1;\n"
    "        if c == \"\\\"\" {\n"
    "            return strings.join(parts, \"\");\n"
    "        }\n"
    "        if c != \"\\\\\" {\n"
    "            if strings.code(c) < 32 {\n"
    "                r.pos -= 1;\n"
    "                fail(r, \"control character in string\");\n"
    "                return \"\";\n"
    "            }\n"
    "            push(parts, c);\n"
    "            continue;\n"
    "        }\n"
    "        let e = peek(r);\n"
    "        r.pos += 1;\n"
    "        if e == \"\\\"\" || e == \"\\\\\" || e == \"/\" {\n"
    "            push(parts, e);\n"
    "        } else if e == \"n\" {\n"
    "            push(parts, \"\\n\");\n"
    "        } else if e == \"t\" {\n"
    "            push(parts, \"\\t\");\n"
    "        } else if e == \"r\" {\n"
    "            push(parts, \"\\r\");\n"
    "        } else if e == \"b\" {\n"
    "            push(parts, strings.fromCode(8));\n"
    "        } else if e == \"f\" {\n"
    "            push(parts, strings.fromCode(12));\n"
    "        } else if e == \"u\" {\n"
    "            var cp = hex4(r);\n"
    "            if cp < 0 {\n"
    "                fail(r, \"bad \\\\u escape\");\n"
    "                return \"\";\n"
    "            }\n"
    "            // A high surrogate has to be followed by \\uDC00-\\uDFFF.\n"
    "            if cp >= 55296 && cp < 56320 {\n"
    "                if peek(r) == \"\\\\\" && r.pos + 1 < len(r.chars) && r.chars[r.pos + 1] == \"u\" {\n"
    "                    r.pos += 2;\n"
    "                    let low = hex4(r);\n"
    "                    if low < 56320 || low > 57343 {\n"
    "                        fail(r, \"bad surrogate pair\");\n"
    "                        return \"\";\n"
    "                    }\n"
    "                    cp = 65536 + (cp - 55296) * 1024 + (low - 56320);\n"
    "                } else {\n"
    "                    fail(r, \"lone surrogate\");\n"
    "                    return \"\";\n"
    "                }\n"
    "            } else if cp >= 56320 && cp < 57344 {\n"
    "                fail(r, \"lone surrogate\");\n"
    "                return \"\";\n"
    "            }\n"
    "            push(parts, strings.fromCode(cp));\n"
    "        } else {\n"
    "            r.pos -= 1;\n"
    "            fail(r, \"unknown escape\");\n"
    "            return \"\";\n"
    "        }\n"
    "    }\n"
    "    return \"\";\n"
    "}\n"
    "\n"
    "func parseNumber(r: Reader): Json {\n"
    "    let start = r.pos;\n"
    "    while r.pos < len(r.chars) {\n"
    "        let c = r.chars[r.pos];\n"
    "        if isDigit(c) || c == \"-\" || c == \"+\" || c == \".\" || c == \"e\" || c == \"E\" {\n"
    "            r.pos += 1;\n"
    "        } else {\n"
    "            break;\n"
    "        }\n"
    "    }\n"
    "    let text = strings.join(r.chars[start:r.pos], \"\");\n"
    "    if !strings.isFloat(text) {\n"
    "        r.pos = start;\n"
    "        fail(r, \"bad number\");\n"
    "        return Json.Null;\n"
    "    }\n"
    "    return Json.Num(strings.toFloat(text));\n"
    "}\n"
    "\n"
    "func literal(r: Reader, word: str): bool {\n"
    "    let cs = strings.chars(word);\n"
    "    if r.pos + len(cs) > len(r.chars) {\n"
    "        return false;\n"
    "    }\n"
    "    var i = 0;\n"
    "    while i < len(cs) {\n"
    "        if r.chars[r.pos + i] != cs[i] {\n"
    "            return false;\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    r.pos += len(cs);\n"
    "    return true;\n"
    "}\n"
    "\n"
    "func parseArray(r: Reader): Json {\n"
    "    r.pos += 1;\n"
    "    var list: [Json] = [];\n"
    "    skipSpace(r);\n"
    "    if peek(r) == \"]\" {\n"
    "        r.pos += 1;\n"
    "        return Json.Arr(list);\n"
    "    }\n"
    "    while true {\n"
    "        push(list, parseValue(r));\n"
    "        if !strings.isEmpty(r.error) {\n"
    "            return Json.Null;\n"
    "        }\n"
    "        skipSpace(r);\n"
    "        let c = peek(r);\n"
    "        r.pos += 1;\n"
    "        if c == \"]\" {\n"
    "            return Json.Arr(list);\n"
    "        }\n"
    "        if c != \",\" {\n"
    "            r.pos -= 1;\n"
    "            fail(r, \"expected `,` or `]`\");\n"
    "            return Json.Null;\n"
    "        }\n"
    "    }\n"
    "    return Json.Null;\n"
    "}\n"
    "\n"
    "func parseObject(r: Reader): Json {\n"
    "    r.pos += 1;\n"
    "    var fields: {str: Json} = {};\n"
    "    skipSpace(r);\n"
    "    if peek(r) == \"}\" {\n"
    "        r.pos += 1;\n"
    "        return Json.Obj(fields);\n"
    "    }\n"
    "    while true {\n"
    "        skipSpace(r);\n"
    "        if peek(r) != \"\\\"\" {\n"
    "            fail(r, \"expected a string key\");\n"
    "            return Json.Null;\n"
    "        }\n"
    "        let key = parseString(r);\n"
    "        if !strings.isEmpty(r.error) {\n"
    "            return Json.Null;\n"
    "        }\n"
    "        skipSpace(r);\n"
    "        if peek(r) != \":\" {\n"
    "            fail(r, \"expected `:`\");\n"
    "            return Json.Null;\n"
    "        }\n"
    "        r.pos += 1;\n"
    "        let value = parseValue(r);\n"
    "        if !strings.isEmpty(r.error) {\n"
    "            return Json.Null;\n"
    "        }\n"
    "        fields[key] = value;\n"
    "        skipSpace(r);\n"
    "        let c = peek(r);\n"
    "        r.pos += 1;\n"
    "        if c == \"}\" {\n"
    "            return Json.Obj(fields);\n"
    "        }\n"
    "        if c != \",\" {\n"
    "            r.pos -= 1;\n"
    "            fail(r, \"expected `,` or `}`\");\n"
    "            return Json.Null;\n"
    "        }\n"
    "    }\n"
    "    return Json.Null;\n"
    "}\n"
    "\n"
    "func parseValue(r: Reader): Json {\n"
    "    skipSpace(r);\n"
    "    let c = peek(r);\n"
    "    if c == \"{\" {\n"
    "        return parseObject(r);\n"
    "    }\n"
    "    if c == \"[\" {\n"
    "        return parseArray(r);\n"
    "    }\n"
    "    if c == \"\\\"\" {\n"
    "        let s = parseString(r);\n"
    "        return Json.Str(s);\n"
    "    }\n"
    "    if c == \"-\" || isDigit(c) {\n"
    "        return parseNumber(r);\n"
    "    }\n"
    "    if c == \"t\" && literal(r, \"true\") {\n"
    "        return Json.Bool(true);\n"
    "    }\n"
    "    if c == \"f\" && literal(r, \"false\") {\n"
    "        return Json.Bool(false);\n"
    "    }\n"
    "    if c == \"n\" && literal(r, \"null\") {\n"
    "        return Json.Null;\n"
    "    }\n"
    "    if strings.isEmpty(c) {\n"
    "        fail(r, \"unexpected end of input\");\n"
    "    } else {\n"
    "        fail(r, \"unexpected `${c}`\");\n"
    "    }\n"
    "    return Json.Null;\n"
    "}\n"
    "\n"
    "// Parses one JSON document. Anything after it other than whitespace is an\n"
    "// error. The message names the line and column.\n"
    "func parse(text: str): result.Result[Json, str] {\n"
    "    let r = Reader { chars: strings.chars(text), pos: 0, error: \"\" };\n"
    "    let value = parseValue(r);\n"
    "    if strings.isEmpty(r.error) {\n"
    "        skipSpace(r);\n"
    "        if r.pos < len(r.chars) {\n"
    "            fail(r, \"unexpected `${r.chars[r.pos]}` after the value\");\n"
    "        }\n"
    "    }\n"
    "    if !strings.isEmpty(r.error) {\n"
    "        let bad: result.Result[Json, str] = result.Result.Failure(r.error);\n"
    "        return bad;\n"
    "    }\n"
    "    let good: result.Result[Json, str] = result.Result.Success(value);\n"
    "    return good;\n"
    "}\n"
    "\n"
    "// The value, or `fallback` if the text does not parse.\n"
    "func parseOr(text: str, fallback: Json): Json {\n"
    "    switch parse(text) {\n"
    "        case Success(v): return v;\n"
    "        case Failure(message): return fallback;\n"
    "    }\n"
    "}\n"
    "\n";

static const char src_path[] =
    "// The `path` module: building and taking apart file paths as text.\n"
    "//\n"
    "// Nothing here touches the disk; pair it with `fs`. Both `/` and `\\` are\n"
    "// read as separators, so a Windows path works anywhere, and everything this\n"
    "// module produces uses `/`, which every platform's file functions accept.\n"
    "\n"
    "import strings;\n"
    "\n"
    "func isSep(c: str): bool {\n"
    "    return c == \"/\" || c == \"\\\\\";\n"
    "}\n"
    "\n"
    "// `a` and `b` with exactly one separator between them. An absolute `b`\n"
    "// replaces `a`, and an empty side is ignored.\n"
    "func join(a: str, b: str): str {\n"
    "    if strings.isEmpty(a) {\n"
    "        return b;\n"
    "    }\n"
    "    if strings.isEmpty(b) {\n"
    "        return a;\n"
    "    }\n"
    "    if isAbs(b) {\n"
    "        return b;\n"
    "    }\n"
    "    var left = a;\n"
    "    while strings.len(left) > 1 && isSep(strings.at(left, strings.len(left) - 1)) {\n"
    "        left = strings.sub(left, 0, strings.len(left) - 1);\n"
    "    }\n"
    "    if isSep(strings.at(left, strings.len(left) - 1)) {\n"
    "        return left + b;\n"
    "    }\n"
    "    return left + \"/\" + b;\n"
    "}\n"
    "\n"
    "// Joins any number of parts left to right.\n"
    "func joinAll(parts: [str]): str {\n"
    "    var out = \"\";\n"
    "    for p in parts {\n"
    "        out = join(out, p);\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// Starts at the root: `/usr`, `\\share`, or `C:/dir`.\n"
    "func isAbs(p: str): bool {\n"
    "    if strings.isEmpty(p) {\n"
    "        return false;\n"
    "    }\n"
    "    if isSep(strings.at(p, 0)) {\n"
    "        return true;\n"
    "    }\n"
    "    return strings.len(p) >= 3 && strings.at(p, 1) == \":\" && isSep(strings.at(p, 2));\n"
    "}\n"
    "\n"
    "// Index just past the last separator, or 0 when there is none.\n"
    "func lastSep(p: str): int {\n"
    "    var i = strings.len(p) - 1;\n"
    "    while i >= 0 {\n"
    "        if isSep(strings.at(p, i)) {\n"
    "            return i;\n"
    "        }\n"
    "        i -= 1;\n"
    "    }\n"
    "    return -1;\n"
    "}\n"
    "\n"
    "// `p` without trailing separators (but a bare root stays as it is).\n"
    "func trimEnd(p: str): str {\n"
    "    var out = p;\n"
    "    while strings.len(out) > 1 && isSep(strings.at(out, strings.len(out) - 1)) {\n"
    "        out = strings.sub(out, 0, strings.len(out) - 1);\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// The last component: `a/b/c.txt` -> `c.txt`.\n"
    "func base(p: str): str {\n"
    "    let t = trimEnd(p);\n"
    "    let i = lastSep(t);\n"
    "    if i < 0 {\n"
    "        return t;\n"
    "    }\n"
    "    if i == 0 && strings.len(t) == 1 {\n"
    "        return t;\n"
    "    }\n"
    "    return strings.sub(t, i + 1, strings.len(t));\n"
    "}\n"
    "\n"
    "// Everything before the last component: `a/b/c.txt` -> `a/b`. `.` when there\n"
    "// is no directory part.\n"
    "func dir(p: str): str {\n"
    "    let t = trimEnd(p);\n"
    "    let i = lastSep(t);\n"
    "    if i < 0 {\n"
    "        return \".\";\n"
    "    }\n"
    "    if i == 0 {\n"
    "        return \"/\";\n"
    "    }\n"
    "    return trimEnd(strings.sub(t, 0, i));\n"
    "}\n"
    "\n"
    "// The extension with its dot, or \"\" when there is none. A name that only\n"
    "// starts with a dot, like `.gitignore`, has no extension.\n"
    "func ext(p: str): str {\n"
    "    let name = base(p);\n"
    "    var i = strings.len(name) - 1;\n"
    "    while i > 0 {\n"
    "        if strings.at(name, i) == \".\" {\n"
    "            return strings.sub(name, i, strings.len(name));\n"
    "        }\n"
    "        i -= 1;\n"
    "    }\n"
    "    return \"\";\n"
    "}\n"
    "\n"
    "// The last component without its extension: `a/c.tar.gz` -> `c.tar`.\n"
    "func stem(p: str): str {\n"
    "    let name = base(p);\n"
    "    let e = ext(p);\n"
    "    return strings.sub(name, 0, strings.len(name) - strings.len(e));\n"
    "}\n"
    "\n"
    "func withExt(p: str, newExt: str): str {\n"
    "    let d = dir(p);\n"
    "    let name = stem(p) + newExt;\n"
    "    if strings.contains(p, \"/\") || strings.contains(p, \"\\\\\") {\n"
    "        return join(d, name);\n"
    "    }\n"
    "    return name;\n"
    "}\n"
    "\n"
    "// The components, without empty ones: `/a//b/` -> `a`, `b`.\n"
    "func parts(p: str): [str] {\n"
    "    var out: [str] = [];\n"
    "    var cur = \"\";\n"
    "    for c in strings.chars(p) {\n"
    "        if isSep(c) {\n"
    "            if !strings.isEmpty(cur) {\n"
    "                push(out, cur);\n"
    "            }\n"
    "            cur = \"\";\n"
    "        } else {\n"
    "            cur = cur + c;\n"
    "        }\n"
    "    }\n"
    "    if !strings.isEmpty(cur) {\n"
    "        push(out, cur);\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// Resolves `.` and `..` and collapses repeated separators, without looking\n"
    "// at the disk. A `..` that has nothing to remove stays at the front of a\n"
    "// relative path and disappears at the root.\n"
    "func clean(p: str): str {\n"
    "    if strings.isEmpty(p) {\n"
    "        return \".\";\n"
    "    }\n"
    "    let absolute = isAbs(p);\n"
    "    var drive = \"\";\n"
    "    var rest = p;\n"
    "    if strings.len(p) >= 2 && strings.at(p, 1) == \":\" {\n"
    "        drive = strings.sub(p, 0, 2);\n"
    "        rest = strings.sub(p, 2, strings.len(p));\n"
    "    }\n"
    "    var out: [str] = [];\n"
    "    for part in parts(rest) {\n"
    "        if part == \".\" {\n"
    "            continue;\n"
    "        }\n"
    "        if part == \"..\" {\n"
    "            if len(out) > 0 && out[len(out) - 1] != \"..\" {\n"
    "                pop(out);\n"
    "            } else if !absolute {\n"
    "                push(out, \"..\");\n"
    "            }\n"
    "            continue;\n"
    "        }\n"
    "        push(out, part);\n"
    "    }\n"
    "    var body = strings.join(out, \"/\");\n"
    "    if absolute {\n"
    "        body = \"/\" + body;\n"
    "    }\n"
    "    if strings.isEmpty(body) {\n"
    "        body = \".\";\n"
    "    }\n"
    "    return drive + body;\n"
    "}\n"
    "\n"
    "// `target` written relative to `from`, both read as plain text and cleaned\n"
    "// first. Both have to be absolute or both relative, else `target` comes back\n"
    "// cleaned.\n"
    "func rel(from: str, target: str): str {\n"
    "    if isAbs(from) != isAbs(target) {\n"
    "        return clean(target);\n"
    "    }\n"
    "    let a = parts(clean(from));\n"
    "    let b = parts(clean(target));\n"
    "    var i = 0;\n"
    "    while i < len(a) && i < len(b) && a[i] == b[i] {\n"
    "        i += 1;\n"
    "    }\n"
    "    var out: [str] = [];\n"
    "    var j = i;\n"
    "    while j < len(a) {\n"
    "        if a[j] != \".\" {\n"
    "            push(out, \"..\");\n"
    "        }\n"
    "        j += 1;\n"
    "    }\n"
    "    var k = i;\n"
    "    while k < len(b) {\n"
    "        push(out, b[k]);\n"
    "        k += 1;\n"
    "    }\n"
    "    if len(out) == 0 {\n"
    "        return \".\";\n"
    "    }\n"
    "    return strings.join(out, \"/\");\n"
    "}\n"
    "\n";

static const char src_hex[] =
    "// The `hex` module: bytes as lowercase hexadecimal text.\n"
    "//\n"
    "// Strings carry bytes, so `encode(\"A\")` is \"41\" and non-ASCII text gives one\n"
    "// pair per UTF-8 byte.\n"
    "\n"
    "// \"hello\" -> \"68656c6c6f\".\n"
    "extern func encode(s: str): str;\n"
    "\n"
    "// The reverse. Upper and lower case digits are both read. Empty when the\n"
    "// text is not valid hex (odd length or a bad digit), so check with\n"
    "// `isValid` first if the empty string is a possible answer.\n"
    "extern func decode(s: str): str;\n"
    "\n"
    "extern func isValid(s: str): bool;\n"
    "\n";

static const char src_base64[] =
    "// The `base64` module.\n"
    "//\n"
    "//     base64.encode(\"hello\")      // \"aGVsbG8=\"\n"
    "//     base64.decode(\"aGVsbG8=\")   // \"hello\"\n"
    "//\n"
    "// `encodeUrl` uses the URL-safe alphabet (`-` and `_`) and leaves off the\n"
    "// padding, the form used in JWTs and URLs. `decode` accepts either alphabet,\n"
    "// with or without padding, and skips whitespace.\n"
    "\n"
    "extern func encode(s: str): str;\n"
    "extern func encodeUrl(s: str): str;\n"
    "\n"
    "// Empty when the text is not valid base64; use `isValid` to tell that from\n"
    "// an encoded empty string.\n"
    "extern func decode(s: str): str;\n"
    "\n"
    "extern func isValid(s: str): bool;\n"
    "\n";

static const char src_hash[] =
    "// The `hash` module: checksums and digests of a string's bytes.\n"
    "//\n"
    "// The digests come back as lowercase hex, the form every tool prints.\n"
    "// `md5` and `sha1` are here for checksums and compatibility with older\n"
    "// formats; use `sha256` for anything security-related.\n"
    "\n"
    "extern func md5(s: str): str;\n"
    "extern func sha1(s: str): str;\n"
    "extern func sha256(s: str): str;\n"
    "\n"
    "// HMAC-SHA256 of `message` under `key`, as hex.\n"
    "extern func hmacSha256(key: str, message: str): str;\n"
    "\n"
    "// CRC-32 (the zip/PNG polynomial), 0 to 4294967295.\n"
    "extern func crc32(s: str): int;\n"
    "\n"
    "// 64-bit FNV-1a. The unsigned result is shown as a signed int, so about\n"
    "// half of the values are negative. Handy for hash-table style bucketing.\n"
    "extern func fnv1a(s: str): int;\n"
    "\n";

static const char src_regex[] =
    "// The `regex` module: regular expressions.\n"
    "//\n"
    "//     regex.isMatch(\"^[a-z]+@[a-z]+\\\\.com$\", email)\n"
    "//     regex.groups(\"(\\\\d+)-(\\\\d+)\", \"tel 555-0199\")      // [\"555-0199\", \"555\", \"0199\"]\n"
    "//     regex.replace(\"\\\\s+\", text, \" \")\n"
    "//\n"
    "// Syntax: literals, `.`, classes `[a-z0-9_]` and `[^...]`, `\\d \\w \\s` and\n"
    "// their capital negations, `\\b \\B`, `^ $`, groups `( )` and `(?: )`,\n"
    "// alternation `|`, and the quantifiers `* + ? {n} {n,} {n,m}`, each with a\n"
    "// lazy form by adding `?`. A pattern may start with `(?i)` (ignore case,\n"
    "// ASCII), `(?s)` (`.` matches newline) or `(?m)` (`^` and `$` match at each\n"
    "// line). There are no backreferences or lookaround.\n"
    "//\n"
    "// Matches are leftmost, and among alternatives the first that works wins.\n"
    "// Positions are in characters, like everywhere else in Solis. A pattern that\n"
    "// is not valid stops the program with an error naming the problem; test with\n"
    "// `isValid` when the pattern comes from outside. A match that would take an\n"
    "// absurd number of steps also stops with an error rather than hanging.\n"
    "\n"
    "import strings;\n"
    "\n"
    "// Whether the pattern matches anywhere in the text.\n"
    "extern func isMatch(pattern: str, text: str): bool;\n"
    "\n"
    "// The first match, or \"\" if there is none. Pair with `isMatch` or `index`\n"
    "// when an empty match is possible.\n"
    "extern func find(pattern: str, text: str): str;\n"
    "\n"
    "// Character index of the first match, or -1.\n"
    "extern func index(pattern: str, text: str): int;\n"
    "\n"
    "// The first match followed by what each group captured, a group that did\n"
    "// not take part being \"\". Empty array when nothing matches.\n"
    "extern func groups(pattern: str, text: str): [str];\n"
    "\n"
    "// Every non-overlapping match.\n"
    "extern func findAll(pattern: str, text: str): [str];\n"
    "\n"
    "// `groups` for every match.\n"
    "extern func allGroups(pattern: str, text: str): [[str]];\n"
    "\n"
    "// Replaces every match. In `with`, `$0` is the whole match, `$1` to `$9` are\n"
    "// groups, and `$$` is a dollar sign.\n"
    "extern func replace(pattern: str, text: str, with: str): str;\n"
    "extern func replaceFirst(pattern: str, text: str, with: str): str;\n"
    "\n"
    "// Splits around every match. Adjacent matches give empty pieces.\n"
    "extern func split(pattern: str, text: str): [str];\n"
    "\n"
    "extern func isValid(pattern: str): bool;\n"
    "extern func groupCount(pattern: str): int;\n"
    "\n"
    "// The whole text matches, not just part of it.\n"
    "func fullMatch(pattern: str, text: str): bool {\n"
    "    return isMatch(\"^(?:\" + pattern + \")$\", text);\n"
    "}\n"
    "\n"
    "func count(pattern: str, text: str): int {\n"
    "    return len(findAll(pattern, text));\n"
    "}\n"
    "\n"
    "// `s` with every character that has a meaning in a pattern escaped, to match\n"
    "// it literally.\n"
    "func escape(s: str): str {\n"
    "    var out = \"\";\n"
    "    for c in strings.chars(s) {\n"
    "        if strings.contains(\"\\\\.^$|?*+()[]{}-\", c) {\n"
    "            out = out + \"\\\\\";\n"
    "        }\n"
    "        out = out + c;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n";

static const char src_csv[] =
    "// The `csv` module: comma-separated values, as in RFC 4180.\n"
    "//\n"
    "//     let rows = csv.parse(\"name,age\\n\\\"Lee, Ann\\\",31\\n\");\n"
    "//     // [[\"name\", \"age\"], [\"Lee, Ann\", \"31\"]]\n"
    "//\n"
    "// A field may be wrapped in double quotes to hold the separator, a newline or\n"
    "// a quote (written twice). Lines end with \\n or \\r\\n. A final newline does\n"
    "// not make an extra empty row. Every cell is text; convert with\n"
    "// `strings.toInt` and friends.\n"
    "\n"
    "import strings;\n"
    "\n"
    "func noCells(): [str] {\n"
    "    var cells: [str] = [];\n"
    "    return cells;\n"
    "}\n"
    "\n"
    "// Rows of cells, split on `sep` (one character).\n"
    "func parseWith(text: str, sep: str): [[str]] {\n"
    "    var rows: [[str]] = [];\n"
    "    var row: [str] = [];\n"
    "    var cell = \"\";\n"
    "    var inQuotes = false;\n"
    "    var pending = false;       // anything seen on this row yet\n"
    "    let cs = strings.chars(text);\n"
    "    let n = len(cs);\n"
    "    var i = 0;\n"
    "    while i < n {\n"
    "        let c = cs[i];\n"
    "        if inQuotes {\n"
    "            if c == \"\\\"\" {\n"
    "                if i + 1 < n && cs[i + 1] == \"\\\"\" {\n"
    "                    cell = cell + \"\\\"\";\n"
    "                    i += 1;\n"
    "                } else {\n"
    "                    inQuotes = false;\n"
    "                }\n"
    "            } else {\n"
    "                cell = cell + c;\n"
    "            }\n"
    "        } else if c == \"\\\"\" && strings.isEmpty(cell) {\n"
    "            inQuotes = true;\n"
    "            pending = true;\n"
    "        } else if c == sep {\n"
    "            push(row, cell);\n"
    "            cell = \"\";\n"
    "            pending = true;\n"
    "        } else if c == \"\\n\" || c == \"\\r\" {\n"
    "            if c == \"\\r\" && i + 1 < n && cs[i + 1] == \"\\n\" {\n"
    "                i += 1;\n"
    "            }\n"
    "            if pending || !strings.isEmpty(cell) || len(row) > 0 {\n"
    "                push(row, cell);\n"
    "                push(rows, row);\n"
    "            }\n"
    "            row = noCells();\n"
    "            cell = \"\";\n"
    "            pending = false;\n"
    "        } else {\n"
    "            cell = cell + c;\n"
    "            pending = true;\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    if pending || !strings.isEmpty(cell) || len(row) > 0 {\n"
    "        push(row, cell);\n"
    "        push(rows, row);\n"
    "    }\n"
    "    return rows;\n"
    "}\n"
    "\n"
    "func parse(text: str): [[str]] {\n"
    "    return parseWith(text, \",\");\n"
    "}\n"
    "\n"
    "// The first row names the columns; each later row becomes a map from column\n"
    "// name to cell. Short rows leave the missing columns out.\n"
    "func records(text: str): [{str: str}] {\n"
    "    let rows = parse(text);\n"
    "    var out: [{str: str}] = [];\n"
    "    if len(rows) == 0 {\n"
    "        return out;\n"
    "    }\n"
    "    let header = rows[0];\n"
    "    var r = 1;\n"
    "    while r < len(rows) {\n"
    "        var rec: {str: str} = {};\n"
    "        var c = 0;\n"
    "        while c < len(header) && c < len(rows[r]) {\n"
    "            rec[header[c]] = rows[r][c];\n"
    "            c += 1;\n"
    "        }\n"
    "        push(out, rec);\n"
    "        r += 1;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// One cell, quoted only if it has to be.\n"
    "func quote(cell: str, sep: str): str {\n"
    "    if strings.contains(cell, sep) || strings.contains(cell, \"\\\"\") || strings.contains(cell, \"\\n\") ||\n"
    "       strings.contains(cell, \"\\r\") || strings.startsWith(cell, \" \") || strings.endsWith(cell, \" \") {\n"
    "        return \"\\\"\" + strings.replace(cell, \"\\\"\", \"\\\"\\\"\") + \"\\\"\";\n"
    "    }\n"
    "    return cell;\n"
    "}\n"
    "\n"
    "func formatWith(rows: [[str]], sep: str): str {\n"
    "    var lines: [str] = [];\n"
    "    for row in rows {\n"
    "        var cells: [str] = [];\n"
    "        for cell in row {\n"
    "            push(cells, quote(cell, sep));\n"
    "        }\n"
    "        push(lines, strings.join(cells, sep));\n"
    "    }\n"
    "    if len(lines) == 0 {\n"
    "        return \"\";\n"
    "    }\n"
    "    return strings.join(lines, \"\\n\") + \"\\n\";\n"
    "}\n"
    "\n"
    "// Text with one line per row, each ending in \\n.\n"
    "func format(rows: [[str]]): str {\n"
    "    return formatWith(rows, \",\");\n"
    "}\n"
    "\n";

static const char src_url[] =
    "// The `url` module: percent-encoding, query strings and splitting URLs.\n"
    "//\n"
    "//     url.encode(\"a b&c\")                    // \"a%20b%26c\"\n"
    "//     url.parseQuery(\"x=1&y=two\")            // {\"x\": \"1\", \"y\": \"two\"}\n"
    "//     url.parse(\"https://u@host:8080/p?q=1#top\")\n"
    "//\n"
    "// Nothing here talks to the network; see `http` for that.\n"
    "\n"
    "import strings;\n"
    "\n"
    "func hexDigit(n: int): str {\n"
    "    return strings.sub(\"0123456789ABCDEF\", n, n + 1);\n"
    "}\n"
    "\n"
    "func isUnreserved(c: str): bool {\n"
    "    return strings.len(c) == 1 && strings.contains(\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~\", c);\n"
    "}\n"
    "\n"
    "// Percent-encodes everything except letters, digits and `-_.~`, byte by\n"
    "// byte in UTF-8.\n"
    "func encode(s: str): str {\n"
    "    var out: [str] = [];\n"
    "    for c in strings.chars(s) {\n"
    "        if isUnreserved(c) {\n"
    "            push(out, c);\n"
    "        } else {\n"
    "            for b in strings.bytes(c) {\n"
    "                push(out, \"%\" + hexDigit(b / 16) + hexDigit(b % 16));\n"
    "            }\n"
    "        }\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "// Reads `%XX` escapes. A malformed escape is left as written. With\n"
    "// `plusIsSpace`, `+` becomes a space, as in form data.\n"
    "func decodeWith(s: str, plusIsSpace: bool): str {\n"
    "    let cs = strings.chars(s);\n"
    "    var bytes: [int] = [];\n"
    "    var i = 0;\n"
    "    while i < len(cs) {\n"
    "        let c = cs[i];\n"
    "        if c == \"%\" && i + 2 < len(cs) {\n"
    "            let h = strings.indexOf(\"0123456789abcdef\", strings.lower(cs[i + 1]));\n"
    "            let l = strings.indexOf(\"0123456789abcdef\", strings.lower(cs[i + 2]));\n"
    "            if h >= 0 && l >= 0 && strings.len(cs[i + 1]) == 1 && strings.len(cs[i + 2]) == 1 {\n"
    "                push(bytes, h * 16 + l);\n"
    "                i += 3;\n"
    "                continue;\n"
    "            }\n"
    "        }\n"
    "        if c == \"+\" && plusIsSpace {\n"
    "            push(bytes, 32);\n"
    "        } else {\n"
    "            for b in strings.bytes(c) {\n"
    "                push(bytes, b);\n"
    "            }\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    return strings.fromBytes(bytes);\n"
    "}\n"
    "\n"
    "func decode(s: str): str {\n"
    "    return decodeWith(s, false);\n"
    "}\n"
    "\n"
    "// `a=1&b=two` into a map; later keys win. Keys and values are decoded, and a\n"
    "// key with no `=` maps to \"\". A leading `?` is ignored.\n"
    "func parseQuery(q: str): {str: str} {\n"
    "    var out: {str: str} = {};\n"
    "    var text = q;\n"
    "    if strings.startsWith(text, \"?\") {\n"
    "        text = strings.sub(text, 1, strings.len(text));\n"
    "    }\n"
    "    if strings.isEmpty(text) {\n"
    "        return out;\n"
    "    }\n"
    "    for pair in strings.split(text, \"&\") {\n"
    "        if strings.isEmpty(pair) {\n"
    "            continue;\n"
    "        }\n"
    "        let eq = strings.indexOf(pair, \"=\");\n"
    "        if eq < 0 {\n"
    "            out[decodeWith(pair, true)] = \"\";\n"
    "        } else {\n"
    "            out[decodeWith(strings.sub(pair, 0, eq), true)] = decodeWith(strings.sub(pair, eq + 1, strings.len(pair)), true);\n"
    "        }\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// A map as `a=1&b=two`, in insertion order, encoded. No leading `?`.\n"
    "func buildQuery(params: {str: str}): str {\n"
    "    var parts: [str] = [];\n"
    "    for k in keys(params) {\n"
    "        push(parts, encode(k) + \"=\" + encode(params[k]));\n"
    "    }\n"
    "    return strings.join(parts, \"&\");\n"
    "}\n"
    "\n"
    "struct Url {\n"
    "    scheme: str;\n"
    "    user: str;\n"
    "    host: str;\n"
    "    port: int;         // 0 when the URL does not give one\n"
    "    path: str;\n"
    "    query: str;        // without the `?`\n"
    "    fragment: str;     // without the `#`\n"
    "}\n"
    "\n"
    "// Splits `scheme://user@host:port/path?query#fragment`. Every part is\n"
    "// optional; what is missing comes back empty (port 0). Nothing is decoded.\n"
    "func parse(text: str): Url {\n"
    "    var rest = text;\n"
    "    var fragment = \"\";\n"
    "    var query = \"\";\n"
    "    var scheme = \"\";\n"
    "    var user = \"\";\n"
    "    var host = \"\";\n"
    "    var port = 0;\n"
    "\n"
    "    let hash = strings.indexOf(rest, \"#\");\n"
    "    if hash >= 0 {\n"
    "        fragment = strings.sub(rest, hash + 1, strings.len(rest));\n"
    "        rest = strings.sub(rest, 0, hash);\n"
    "    }\n"
    "    let q = strings.indexOf(rest, \"?\");\n"
    "    if q >= 0 {\n"
    "        query = strings.sub(rest, q + 1, strings.len(rest));\n"
    "        rest = strings.sub(rest, 0, q);\n"
    "    }\n"
    "    let sep = strings.indexOf(rest, \"://\");\n"
    "    if sep > 0 {\n"
    "        scheme = strings.lower(strings.sub(rest, 0, sep));\n"
    "        rest = strings.sub(rest, sep + 3, strings.len(rest));\n"
    "        var authority = rest;\n"
    "        var path = \"\";\n"
    "        let slash = strings.indexOf(rest, \"/\");\n"
    "        if slash >= 0 {\n"
    "            authority = strings.sub(rest, 0, slash);\n"
    "            path = strings.sub(rest, slash, strings.len(rest));\n"
    "        }\n"
    "        let at = strings.indexOf(authority, \"@\");\n"
    "        if at >= 0 {\n"
    "            user = strings.sub(authority, 0, at);\n"
    "            authority = strings.sub(authority, at + 1, strings.len(authority));\n"
    "        }\n"
    "        host = authority;\n"
    "        let colon = strings.indexOf(authority, \":\");\n"
    "        if colon >= 0 && !strings.startsWith(authority, \"[\") {\n"
    "            let digits = strings.sub(authority, colon + 1, strings.len(authority));\n"
    "            if strings.isInt(digits) {\n"
    "                port = strings.toInt(digits);\n"
    "                host = strings.sub(authority, 0, colon);\n"
    "            }\n"
    "        }\n"
    "        return Url { scheme: scheme, user: user, host: host, port: port, path: path, query: query, fragment: fragment };\n"
    "    }\n"
    "    return Url { scheme: \"\", user: \"\", host: \"\", port: 0, path: rest, query: query, fragment: fragment };\n"
    "}\n"
    "\n"
    "// The pieces back into text. A zero port is left out.\n"
    "func format(u: Url): str {\n"
    "    var out = \"\";\n"
    "    if !strings.isEmpty(u.scheme) {\n"
    "        out = u.scheme + \"://\";\n"
    "        if !strings.isEmpty(u.user) {\n"
    "            out = out + u.user + \"@\";\n"
    "        }\n"
    "        out = out + u.host;\n"
    "        if u.port != 0 {\n"
    "            out = out + \":\" + strings.fromInt(u.port);\n"
    "        }\n"
    "    }\n"
    "    out = out + u.path;\n"
    "    if !strings.isEmpty(u.query) {\n"
    "        out = out + \"?\" + u.query;\n"
    "    }\n"
    "    if !strings.isEmpty(u.fragment) {\n"
    "        out = out + \"#\" + u.fragment;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n";

static const char src_datetime[] =
    "// The `datetime` module: dates and times in UTC, as plain numbers and text.\n"
    "//\n"
    "//     let t = datetime.fromUnix(1700000000);\n"
    "//     datetime.format(t, \"%Y-%m-%d %H:%M\")       // \"2023-11-14 22:13\"\n"
    "//     datetime.toUnix(datetime.make(2024, 2, 29, 12, 0, 0))\n"
    "//\n"
    "// This module is pure: it never reads the clock. Get the current time with\n"
    "// `time.nowSec()` and pass it in. There are no time zones; everything is UTC.\n"
    "// The calendar is the proleptic Gregorian one, so negative Unix times and\n"
    "// years before 1970 work.\n"
    "\n"
    "import result;\n"
    "import strings;\n"
    "\n"
    "struct DateTime {\n"
    "    year: int;\n"
    "    month: int;        // 1 to 12\n"
    "    day: int;          // 1 to 31\n"
    "    hour: int;\n"
    "    minute: int;\n"
    "    second: int;\n"
    "    weekday: int;      // 0 is Sunday\n"
    "}\n"
    "\n"
    "// Division and remainder that round down, so negative times split properly.\n"
    "func floorDiv(a: int, b: int): int {\n"
    "    var q = a / b;\n"
    "    if a % b != 0 && ((a < 0) != (b < 0)) {\n"
    "        q -= 1;\n"
    "    }\n"
    "    return q;\n"
    "}\n"
    "\n"
    "func floorMod(a: int, b: int): int {\n"
    "    return a - floorDiv(a, b) * b;\n"
    "}\n"
    "\n"
    "func isLeap(year: int): bool {\n"
    "    return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;\n"
    "}\n"
    "\n"
    "func daysInMonth(year: int, month: int): int {\n"
    "    if month == 2 {\n"
    "        if isLeap(year) {\n"
    "            return 29;\n"
    "        }\n"
    "        return 28;\n"
    "    }\n"
    "    if month == 4 || month == 6 || month == 9 || month == 11 {\n"
    "        return 30;\n"
    "    }\n"
    "    return 31;\n"
    "}\n"
    "\n"
    "// Days since 1970-01-01 for a calendar date (Howard Hinnant's algorithm).\n"
    "func daysFromCivil(year: int, month: int, day: int): int {\n"
    "    var y = year;\n"
    "    if month <= 2 {\n"
    "        y -= 1;\n"
    "    }\n"
    "    let era = floorDiv(y, 400);\n"
    "    let yoe = y - era * 400;\n"
    "    var mp = month - 3;\n"
    "    if month <= 2 {\n"
    "        mp = month + 9;\n"
    "    }\n"
    "    let doy = (153 * mp + 2) / 5 + day - 1;\n"
    "    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;\n"
    "    return era * 146097 + doe - 719468;\n"
    "}\n"
    "\n"
    "// The time `t` seconds after 1970-01-01 00:00:00 UTC.\n"
    "func fromUnix(t: int): DateTime {\n"
    "    let days = floorDiv(t, 86400);\n"
    "    let secs = floorMod(t, 86400);\n"
    "    let z = days + 719468;\n"
    "    let era = floorDiv(z, 146097);\n"
    "    let doe = z - era * 146097;\n"
    "    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;\n"
    "    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);\n"
    "    let mp = (5 * doy + 2) / 153;\n"
    "    let day = doy - (153 * mp + 2) / 5 + 1;\n"
    "    var month = mp + 3;\n"
    "    if mp >= 10 {\n"
    "        month = mp - 9;\n"
    "    }\n"
    "    var year = yoe + era * 400;\n"
    "    if month <= 2 {\n"
    "        year += 1;\n"
    "    }\n"
    "    return DateTime {\n"
    "        year: year, month: month, day: day,\n"
    "        hour: secs / 3600, minute: (secs % 3600) / 60, second: secs % 60,\n"
    "        weekday: floorMod(days + 4, 7),\n"
    "    };\n"
    "}\n"
    "\n"
    "func toUnix(d: DateTime): int {\n"
    "    return daysFromCivil(d.year, d.month, d.day) * 86400 + d.hour * 3600 + d.minute * 60 + d.second;\n"
    "}\n"
    "\n"
    "// A date and time, with out-of-range parts carried over: month 13 is\n"
    "// January of the next year, second 75 is a minute and fifteen seconds.\n"
    "func make(year: int, month: int, day: int, hour: int, minute: int, second: int): DateTime {\n"
    "    let y = year + floorDiv(month - 1, 12);\n"
    "    let m = floorMod(month - 1, 12) + 1;\n"
    "    return fromUnix(daysFromCivil(y, m, 1) * 86400 + (day - 1) * 86400 + hour * 3600 + minute * 60 + second);\n"
    "}\n"
    "\n"
    "func addSeconds(d: DateTime, n: int): DateTime {\n"
    "    return fromUnix(toUnix(d) + n);\n"
    "}\n"
    "\n"
    "func addDays(d: DateTime, n: int): DateTime {\n"
    "    return fromUnix(toUnix(d) + n * 86400);\n"
    "}\n"
    "\n"
    "// Months are calendar months; the day is clamped to the end of a shorter one\n"
    "// (January 31st plus one month is February 28th or 29th).\n"
    "func addMonths(d: DateTime, n: int): DateTime {\n"
    "    let total = d.year * 12 + (d.month - 1) + n;\n"
    "    let y = floorDiv(total, 12);\n"
    "    let m = floorMod(total, 12) + 1;\n"
    "    var day = d.day;\n"
    "    let last = daysInMonth(y, m);\n"
    "    if day > last {\n"
    "        day = last;\n"
    "    }\n"
    "    return make(y, m, day, d.hour, d.minute, d.second);\n"
    "}\n"
    "\n"
    "// 1 for January 1st.\n"
    "func dayOfYear(d: DateTime): int {\n"
    "    return daysFromCivil(d.year, d.month, d.day) - daysFromCivil(d.year, 1, 1) + 1;\n"
    "}\n"
    "\n"
    "// Whole seconds from `a` to `b`.\n"
    "func diffSeconds(a: DateTime, b: DateTime): int {\n"
    "    return toUnix(b) - toUnix(a);\n"
    "}\n"
    "\n"
    "func monthName(month: int): str {\n"
    "    let names = [\"January\", \"February\", \"March\", \"April\", \"May\", \"June\", \"July\",\n"
    "                 \"August\", \"September\", \"October\", \"November\", \"December\"];\n"
    "    if month < 1 || month > 12 {\n"
    "        return \"\";\n"
    "    }\n"
    "    return names[month - 1];\n"
    "}\n"
    "\n"
    "func dayName(weekday: int): str {\n"
    "    let names = [\"Sunday\", \"Monday\", \"Tuesday\", \"Wednesday\", \"Thursday\", \"Friday\", \"Saturday\"];\n"
    "    if weekday < 0 || weekday > 6 {\n"
    "        return \"\";\n"
    "    }\n"
    "    return names[weekday];\n"
    "}\n"
    "\n"
    "func pad(n: int, width: int): str {\n"
    "    return strings.padLeft(strings.fromInt(n), width, \"0\");\n"
    "}\n"
    "\n"
    "// Formats with these codes, as in C's strftime:\n"
    "//   %Y year  %y two-digit year  %m month  %d day  %e day, space padded\n"
    "//   %H hour (24)  %I hour (12)  %M minute  %S second  %p AM or PM\n"
    "//   %B month name  %b short month  %A day name  %a short day  %j day of year\n"
    "//   %F is %Y-%m-%d  %T is %H:%M:%S  %s Unix seconds  %Z is UTC  %% is %\n"
    "func format(d: DateTime, fmt: str): str {\n"
    "    var out: [str] = [];\n"
    "    let cs = strings.chars(fmt);\n"
    "    var i = 0;\n"
    "    while i < len(cs) {\n"
    "        let c = cs[i];\n"
    "        if c != \"%\" || i + 1 >= len(cs) {\n"
    "            push(out, c);\n"
    "            i += 1;\n"
    "            continue;\n"
    "        }\n"
    "        let f = cs[i + 1];\n"
    "        i += 2;\n"
    "        if f == \"Y\" {\n"
    "            push(out, strings.fromInt(d.year));\n"
    "        } else if f == \"y\" {\n"
    "            push(out, pad(floorMod(d.year, 100), 2));\n"
    "        } else if f == \"m\" {\n"
    "            push(out, pad(d.month, 2));\n"
    "        } else if f == \"d\" {\n"
    "            push(out, pad(d.day, 2));\n"
    "        } else if f == \"e\" {\n"
    "            push(out, strings.padLeft(strings.fromInt(d.day), 2, \" \"));\n"
    "        } else if f == \"H\" {\n"
    "            push(out, pad(d.hour, 2));\n"
    "        } else if f == \"I\" {\n"
    "            var h = d.hour % 12;\n"
    "            if h == 0 {\n"
    "                h = 12;\n"
    "            }\n"
    "            push(out, pad(h, 2));\n"
    "        } else if f == \"M\" {\n"
    "            push(out, pad(d.minute, 2));\n"
    "        } else if f == \"S\" {\n"
    "            push(out, pad(d.second, 2));\n"
    "        } else if f == \"p\" {\n"
    "            if d.hour < 12 {\n"
    "                push(out, \"AM\");\n"
    "            } else {\n"
    "                push(out, \"PM\");\n"
    "            }\n"
    "        } else if f == \"B\" {\n"
    "            push(out, monthName(d.month));\n"
    "        } else if f == \"b\" {\n"
    "            push(out, strings.sub(monthName(d.month), 0, 3));\n"
    "        } else if f == \"A\" {\n"
    "            push(out, dayName(d.weekday));\n"
    "        } else if f == \"a\" {\n"
    "            push(out, strings.sub(dayName(d.weekday), 0, 3));\n"
    "        } else if f == \"j\" {\n"
    "            push(out, pad(dayOfYear(d), 3));\n"
    "        } else if f == \"F\" {\n"
    "            push(out, format(d, \"%Y-%m-%d\"));\n"
    "        } else if f == \"T\" {\n"
    "            push(out, format(d, \"%H:%M:%S\"));\n"
    "        } else if f == \"s\" {\n"
    "            push(out, strings.fromInt(toUnix(d)));\n"
    "        } else if f == \"Z\" {\n"
    "            push(out, \"UTC\");\n"
    "        } else if f == \"%\" {\n"
    "            push(out, \"%\");\n"
    "        } else {\n"
    "            push(out, \"%\" + f);\n"
    "        }\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "// \"2023-11-14T22:13:20Z\".\n"
    "func iso(d: DateTime): str {\n"
    "    return format(d, \"%Y-%m-%dT%H:%M:%SZ\");\n"
    "}\n"
    "\n"
    "// A run of digits `n` characters long at `at`, or -1.\n"
    "func digits(s: str, at: int, n: int): int {\n"
    "    if at + n > strings.len(s) {\n"
    "        return -1;\n"
    "    }\n"
    "    let piece = strings.sub(s, at, at + n);\n"
    "    var i = 0;\n"
    "    while i < n {\n"
    "        if !strings.contains(\"0123456789\", strings.at(piece, i)) {\n"
    "            return -1;\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    return strings.toInt(piece);\n"
    "}\n"
    "\n"
    "// Reads `YYYY-MM-DD`, optionally followed by `T` or a space and `HH:MM` or\n"
    "// `HH:MM:SS`, optional fractional seconds (dropped), and `Z` or an offset\n"
    "// like `+02:00` (applied, so the result is UTC).\n"
    "func parse(text: str): result.Result[DateTime, str] {\n"
    "    let s = strings.trim(text);\n"
    "    let bad: result.Result[DateTime, str] = result.Result.Failure(\"not a date: \" + text);\n"
    "    let year = digits(s, 0, 4);\n"
    "    let month = digits(s, 5, 2);\n"
    "    let day = digits(s, 8, 2);\n"
    "    if year < 0 || month < 1 || month > 12 || day < 1 || strings.at(s, 4) != \"-\" || strings.at(s, 7) != \"-\" {\n"
    "        return bad;\n"
    "    }\n"
    "    if day > daysInMonth(year, month) {\n"
    "        return bad;\n"
    "    }\n"
    "    var hour = 0;\n"
    "    var minute = 0;\n"
    "    var second = 0;\n"
    "    var offset = 0;\n"
    "    var pos = 10;\n"
    "    if strings.len(s) > 10 {\n"
    "        let sep = strings.at(s, 10);\n"
    "        if sep != \"T\" && sep != \" \" {\n"
    "            return bad;\n"
    "        }\n"
    "        hour = digits(s, 11, 2);\n"
    "        minute = digits(s, 14, 2);\n"
    "        if hour < 0 || hour > 23 || minute < 0 || minute > 59 || strings.at(s, 13) != \":\" {\n"
    "            return bad;\n"
    "        }\n"
    "        pos = 16;\n"
    "        if strings.at(s, 16) == \":\" {\n"
    "            second = digits(s, 17, 2);\n"
    "            if second < 0 || second > 60 {\n"
    "                return bad;\n"
    "            }\n"
    "            pos = 19;\n"
    "            if strings.at(s, 19) == \".\" {\n"
    "                pos += 1;\n"
    "                while pos < strings.len(s) && strings.contains(\"0123456789\", strings.at(s, pos)) {\n"
    "                    pos += 1;\n"
    "                }\n"
    "            }\n"
    "        }\n"
    "        if pos < strings.len(s) {\n"
    "            let z = strings.at(s, pos);\n"
    "            if z == \"Z\" || z == \"z\" {\n"
    "                pos += 1;\n"
    "            } else if z == \"+\" || z == \"-\" {\n"
    "                let oh = digits(s, pos + 1, 2);\n"
    "                var om = 0;\n"
    "                var used = 3;\n"
    "                if strings.at(s, pos + 3) == \":\" {\n"
    "                    om = digits(s, pos + 4, 2);\n"
    "                    used = 6;\n"
    "                } else if digits(s, pos + 3, 2) >= 0 {\n"
    "                    om = digits(s, pos + 3, 2);\n"
    "                    used = 5;\n"
    "                }\n"
    "                if oh < 0 || om < 0 {\n"
    "                    return bad;\n"
    "                }\n"
    "                offset = oh * 3600 + om * 60;\n"
    "                if z == \"-\" {\n"
    "                    offset = 0 - offset;\n"
    "                }\n"
    "                pos += used;\n"
    "            }\n"
    "        }\n"
    "        if pos != strings.len(s) {\n"
    "            return bad;\n"
    "        }\n"
    "    }\n"
    "    let ok: result.Result[DateTime, str] =\n"
    "        result.Result.Success(fromUnix(toUnix(make(year, month, day, hour, minute, second)) - offset));\n"
    "    return ok;\n"
    "}\n"
    "\n";

static const char src_lists[] =
    "// The `lists` module: helpers for arrays.\n"
    "//\n"
    "// Everything here returns a new array and leaves its arguments alone. The\n"
    "// language has no function values, so there is no `map` or `filter`; write\n"
    "// the loop. What is here is what a loop would otherwise have to repeat.\n"
    "\n"
    "import math;\n"
    "\n"
    "func concat[T](a: [T], b: [T]): [T] {\n"
    "    var out: [T] = [];\n"
    "    for x in a {\n"
    "        push(out, x);\n"
    "    }\n"
    "    for x in b {\n"
    "        push(out, x);\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func flatten[T](parts: [[T]]): [T] {\n"
    "    var out: [T] = [];\n"
    "    for part in parts {\n"
    "        for x in part {\n"
    "            push(out, x);\n"
    "        }\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func reversed[T](xs: [T]): [T] {\n"
    "    var out: [T] = [];\n"
    "    var i = len(xs) - 1;\n"
    "    while i >= 0 {\n"
    "        push(out, xs[i]);\n"
    "        i -= 1;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// `n` copies of `x`.\n"
    "func repeat[T](x: T, n: int): [T] {\n"
    "    var out: [T] = [];\n"
    "    var i = 0;\n"
    "    while i < n {\n"
    "        push(out, x);\n"
    "        i += 1;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// Consecutive pieces of at most `size` elements.\n"
    "func chunks[T](xs: [T], size: int): [[T]] {\n"
    "    var out: [[T]] = [];\n"
    "    if size <= 0 {\n"
    "        return out;\n"
    "    }\n"
    "    var i = 0;\n"
    "    while i < len(xs) {\n"
    "        var end = i + size;\n"
    "        if end > len(xs) {\n"
    "            end = len(xs);\n"
    "        }\n"
    "        push(out, xs[i:end]);\n"
    "        i = end;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// The first and last element, or `fallback` for an empty array.\n"
    "func firstOr[T](xs: [T], fallback: T): T {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    return xs[0];\n"
    "}\n"
    "\n"
    "func lastOr[T](xs: [T], fallback: T): T {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    return xs[len(xs) - 1];\n"
    "}\n"
    "\n"
    "func sumInt(xs: [int]): int {\n"
    "    var total = 0;\n"
    "    for x in xs {\n"
    "        total += x;\n"
    "    }\n"
    "    return total;\n"
    "}\n"
    "\n"
    "func sumFloat(xs: [float]): float {\n"
    "    var total = 0.0;\n"
    "    for x in xs {\n"
    "        total += x;\n"
    "    }\n"
    "    return total;\n"
    "}\n"
    "\n"
    "// The smallest and largest element, or `fallback` for an empty array.\n"
    "func minInt(xs: [int], fallback: int): int {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    var best = xs[0];\n"
    "    for x in xs {\n"
    "        if x < best {\n"
    "            best = x;\n"
    "        }\n"
    "    }\n"
    "    return best;\n"
    "}\n"
    "\n"
    "func maxInt(xs: [int], fallback: int): int {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    var best = xs[0];\n"
    "    for x in xs {\n"
    "        if x > best {\n"
    "            best = x;\n"
    "        }\n"
    "    }\n"
    "    return best;\n"
    "}\n"
    "\n"
    "func minFloat(xs: [float], fallback: float): float {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    var best = xs[0];\n"
    "    for x in xs {\n"
    "        if x < best {\n"
    "            best = x;\n"
    "        }\n"
    "    }\n"
    "    return best;\n"
    "}\n"
    "\n"
    "func maxFloat(xs: [float], fallback: float): float {\n"
    "    if len(xs) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    var best = xs[0];\n"
    "    for x in xs {\n"
    "        if x > best {\n"
    "            best = x;\n"
    "        }\n"
    "    }\n"
    "    return best;\n"
    "}\n"
    "\n"
    "// The mean, or 0.0 for an empty array.\n"
    "func mean(xs: [float]): float {\n"
    "    if len(xs) == 0 {\n"
    "        return 0.0;\n"
    "    }\n"
    "    return sumFloat(xs) / math.toFloat(len(xs));\n"
    "}\n"
    "\n"
    "// Without repeats, keeping the first occurrence of each.\n"
    "func uniqueInts(xs: [int]): [int] {\n"
    "    var seen: {int: bool} = {};\n"
    "    var out: [int] = [];\n"
    "    for x in xs {\n"
    "        if !contains(seen, x) {\n"
    "            seen[x] = true;\n"
    "            push(out, x);\n"
    "        }\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func uniqueStrs(xs: [str]): [str] {\n"
    "    var seen: {str: bool} = {};\n"
    "    var out: [str] = [];\n"
    "    for x in xs {\n"
    "        if !contains(seen, x) {\n"
    "            seen[x] = true;\n"
    "            push(out, x);\n"
    "        }\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// A sorted copy; the argument is untouched.\n"
    "func sortedInts(xs: [int]): [int] {\n"
    "    var out = xs[:];\n"
    "    sort(out);\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func sortedFloats(xs: [float]): [float] {\n"
    "    var out = xs[:];\n"
    "    sort(out);\n"
    "    return out;\n"
    "}\n"
    "\n"
    "func sortedStrs(xs: [str]): [str] {\n"
    "    var out = xs[:];\n"
    "    sort(out);\n"
    "    return out;\n"
    "}\n"
    "\n";

static const char src_flags[] =
    "// The `flags` module: command-line options.\n"
    "//\n"
    "//     let f = flags.parse(os.argv(), [\"out\", \"n\"]);\n"
    "//     let n = flags.getInt(f, \"n\", 10);\n"
    "//     for file in f.positional { ... }\n"
    "//\n"
    "// Recognised forms: `--name`, `--name=value`, `--name value`, `-x`, `-xyz`\n"
    "// (three short flags), `-n 5`, and `--` to say the rest are positional. A\n"
    "// bare `--name` is only given a value from the next argument if its name is\n"
    "// in `valued`; otherwise it is a switch whose value is \"true\". Names are\n"
    "// stored without their dashes.\n"
    "\n"
    "import strings;\n"
    "\n"
    "struct Flags {\n"
    "    named: {str: str};\n"
    "    positional: [str];\n"
    "}\n"
    "\n"
    "func parse(args: [str], valued: [str]): Flags {\n"
    "    var named: {str: str} = {};\n"
    "    var positional: [str] = [];\n"
    "    var i = 0;\n"
    "    var onlyPositional = false;\n"
    "    while i < len(args) {\n"
    "        let a = args[i];\n"
    "        i += 1;\n"
    "        if onlyPositional || a == \"-\" || !strings.startsWith(a, \"-\") {\n"
    "            push(positional, a);\n"
    "            continue;\n"
    "        }\n"
    "        if a == \"--\" {\n"
    "            onlyPositional = true;\n"
    "            continue;\n"
    "        }\n"
    "        if strings.startsWith(a, \"--\") {\n"
    "            let body = strings.sub(a, 2, strings.len(a));\n"
    "            let eq = strings.indexOf(body, \"=\");\n"
    "            if eq >= 0 {\n"
    "                named[strings.sub(body, 0, eq)] = strings.sub(body, eq + 1, strings.len(body));\n"
    "            } else if contains(valued, body) && i < len(args) {\n"
    "                named[body] = args[i];\n"
    "                i += 1;\n"
    "            } else {\n"
    "                named[body] = \"true\";\n"
    "            }\n"
    "            continue;\n"
    "        }\n"
    "        // short flags: -abc\n"
    "        let letters = strings.chars(strings.sub(a, 1, strings.len(a)));\n"
    "        var k = 0;\n"
    "        while k < len(letters) {\n"
    "            let letter = letters[k];\n"
    "            if contains(valued, letter) {\n"
    "                if k + 1 < len(letters) {\n"
    "                    named[letter] = strings.join(letters[k + 1:], \"\");\n"
    "                } else if i < len(args) {\n"
    "                    named[letter] = args[i];\n"
    "                    i += 1;\n"
    "                } else {\n"
    "                    named[letter] = \"\";\n"
    "                }\n"
    "                break;\n"
    "            }\n"
    "            named[letter] = \"true\";\n"
    "            k += 1;\n"
    "        }\n"
    "    }\n"
    "    return Flags { named: named, positional: positional };\n"
    "}\n"
    "\n"
    "func has(f: Flags, name: str): bool {\n"
    "    return contains(f.named, name);\n"
    "}\n"
    "\n"
    "func get(f: Flags, name: str, fallback: str): str {\n"
    "    if contains(f.named, name) {\n"
    "        return f.named[name];\n"
    "    }\n"
    "    return fallback;\n"
    "}\n"
    "\n"
    "func getInt(f: Flags, name: str, fallback: int): int {\n"
    "    if contains(f.named, name) && strings.isInt(f.named[name]) {\n"
    "        return strings.toInt(f.named[name]);\n"
    "    }\n"
    "    return fallback;\n"
    "}\n"
    "\n"
    "func getFloat(f: Flags, name: str, fallback: float): float {\n"
    "    if contains(f.named, name) && strings.isFloat(f.named[name]) {\n"
    "        return strings.toFloat(f.named[name]);\n"
    "    }\n"
    "    return fallback;\n"
    "}\n"
    "\n"
    "// True when the flag is present and not \"false\" or \"0\".\n"
    "func getBool(f: Flags, name: str): bool {\n"
    "    if !contains(f.named, name) {\n"
    "        return false;\n"
    "    }\n"
    "    let v = strings.lower(f.named[name]);\n"
    "    return v != \"false\" && v != \"0\" && v != \"no\" && v != \"off\";\n"
    "}\n"
    "\n";

static const char src_log[] =
    "// The `log` module: leveled messages on standard error, one line each.\n"
    "//\n"
    "//     log.info(\"listening on port ${port}\");\n"
    "//     // 2026-10-04T18:33:07Z INFO listening on port 8080\n"
    "//\n"
    "// Messages below the current level are dropped. The default level is `info`.\n"
    "// Only the standard interpreter opens this, since it needs the clock and the\n"
    "// error stream.\n"
    "\n"
    "import io;\n"
    "import strings;\n"
    "import time;\n"
    "\n"
    "let DEBUG = 0;\n"
    "let INFO = 1;\n"
    "let WARN = 2;\n"
    "let ERROR = 3;\n"
    "let OFF = 4;\n"
    "\n"
    "var level = 1;\n"
    "\n"
    "func setLevel(n: int) {\n"
    "    level = n;\n"
    "}\n"
    "\n"
    "func getLevel(): int {\n"
    "    return level;\n"
    "}\n"
    "\n"
    "// \"debug\", \"info\", \"warn\", \"error\" or \"off\" (any case); other text leaves the\n"
    "// level unchanged. Returns whether it was understood.\n"
    "func setLevelByName(name: str): bool {\n"
    "    let n = strings.lower(name);\n"
    "    if n == \"debug\" {\n"
    "        level = DEBUG;\n"
    "    } else if n == \"info\" {\n"
    "        level = INFO;\n"
    "    } else if n == \"warn\" || n == \"warning\" {\n"
    "        level = WARN;\n"
    "    } else if n == \"error\" {\n"
    "        level = ERROR;\n"
    "    } else if n == \"off\" || n == \"none\" {\n"
    "        level = OFF;\n"
    "    } else {\n"
    "        return false;\n"
    "    }\n"
    "    return true;\n"
    "}\n"
    "\n"
    "func emit(at: int, label: str, message: str) {\n"
    "    if at >= level {\n"
    "        io.errLine(time.iso() + \" \" + label + \" \" + message);\n"
    "    }\n"
    "}\n"
    "\n"
    "func debug(message: str) {\n"
    "    emit(DEBUG, \"DEBUG\", message);\n"
    "}\n"
    "\n"
    "func info(message: str) {\n"
    "    emit(INFO, \"INFO\", message);\n"
    "}\n"
    "\n"
    "func warn(message: str) {\n"
    "    emit(WARN, \"WARN\", message);\n"
    "}\n"
    "\n"
    "func error(message: str) {\n"
    "    emit(ERROR, \"ERROR\", message);\n"
    "}\n"
    "\n";

static const char src_http[] =
    "// The `http` module: an HTTP and HTTPS client.\n"
    "//\n"
    "//     let r = http.get(\"https://example.com/api\");\n"
    "//     if http.ok(r) { print(r.body); } else { print(\"failed: ${r.status} ${r.error}\"); }\n"
    "//\n"
    "// It runs the `curl` program, which ships with Windows 10 and later, macOS,\n"
    "// and almost every Linux, so HTTPS, redirects and proxies behave as they do\n"
    "// in the shell. Without `curl` on the PATH every request comes back with\n"
    "// status 0 and an error saying so. Only the standard interpreter opens this.\n"
    "//\n"
    "// Failures that are not HTTP statuses (no network, bad host, timeout) give\n"
    "// status 0 and the reason in `error`. An HTTP error status such as 404 is a\n"
    "// normal response: look at `status`, or call `ok`.\n"
    "//\n"
    "// Bodies and headers are passed through files and quoted arguments, so any\n"
    "// text is safe to send. On Windows the command goes through `cmd.exe`, so\n"
    "// avoid `%` in a URL or header.\n"
    "\n"
    "import fs;\n"
    "import os;\n"
    "import rand;\n"
    "import strings;\n"
    "import time;\n"
    "\n"
    "struct Response {\n"
    "    status: int;               // 0 if no response arrived\n"
    "    body: str;\n"
    "    headers: {str: str};       // names in lower case; the last response if redirected\n"
    "    error: str;                // empty when a response arrived\n"
    "}\n"
    "\n"
    "// Seconds before a request is given up. Change with `setTimeout`.\n"
    "var timeoutSeconds = 30;\n"
    "\n"
    "func setTimeout(seconds: int) {\n"
    "    timeoutSeconds = seconds;\n"
    "}\n"
    "\n"
    "// 2xx, and nothing went wrong on the way.\n"
    "func ok(r: Response): bool {\n"
    "    return r.status >= 200 && r.status < 300 && strings.isEmpty(r.error);\n"
    "}\n"
    "\n"
    "func shellQuote(s: str): str {\n"
    "    if os.isWindows() {\n"
    "        return \"\\\"\" + strings.replace(s, \"\\\"\", \"\\\\\\\"\") + \"\\\"\";\n"
    "    }\n"
    "    return \"'\" + strings.replace(s, \"'\", \"'\\\\''\") + \"'\";\n"
    "}\n"
    "\n"
    "func tempBase(): str {\n"
    "    var dir = os.envOr(\"TMPDIR\", \"\");\n"
    "    if strings.isEmpty(dir) {\n"
    "        if os.isWindows() {\n"
    "            dir = os.envOr(\"TEMP\", \".\");\n"
    "        } else {\n"
    "            dir = \"/tmp\";\n"
    "        }\n"
    "    }\n"
    "    return dir + \"/solis-http-\" + strings.fromInt(time.nowMs()) + \"-\" + strings.fromInt(rand.below(1000000));\n"
    "}\n"
    "\n"
    "func noHeaders(): {str: str} {\n"
    "    var h: {str: str} = {};\n"
    "    return h;\n"
    "}\n"
    "\n"
    "func parseHeaders(text: str): {str: str} {\n"
    "    var out: {str: str} = {};\n"
    "    for raw in strings.split(strings.replace(text, \"\\r\\n\", \"\\n\"), \"\\n\") {\n"
    "        if strings.startsWith(raw, \"HTTP/\") {\n"
    "            out = noHeaders();\n"
    "            continue;\n"
    "        }\n"
    "        let colon = strings.indexOf(raw, \":\");\n"
    "        if colon > 0 {\n"
    "            out[strings.lower(strings.sub(raw, 0, colon))] = strings.trim(strings.sub(raw, colon + 1, strings.len(raw)));\n"
    "        }\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// Sends one request. `body` may be empty; `headers` maps names to values.\n"
    "func request(method: str, url: str, body: str, headers: {str: str}): Response {\n"
    "    let base = tempBase();\n"
    "    let headerFile = base + \".h\";\n"
    "    let bodyFile = base + \".b\";\n"
    "    let errFile = base + \".e\";\n"
    "    let sendFile = base + \".s\";\n"
    "    var cmd = \"curl -sS -L --max-time \" + strings.fromInt(timeoutSeconds) + \" -X \" + shellQuote(method);\n"
    "    cmd = cmd + \" -D \" + shellQuote(headerFile) + \" -o \" + shellQuote(bodyFile);\n"
    "    cmd = cmd + \" -w \" + shellQuote(\"%{http_code}\");\n"
    "    for name in keys(headers) {\n"
    "        cmd = cmd + \" -H \" + shellQuote(name + \": \" + headers[name]);\n"
    "    }\n"
    "    if !strings.isEmpty(body) {\n"
    "        fs.write(sendFile, body);\n"
    "        cmd = cmd + \" --data-binary \" + shellQuote(\"@\" + sendFile);\n"
    "    }\n"
    "    cmd = cmd + \" \" + shellQuote(url) + \" 2> \" + shellQuote(errFile);\n"
    "\n"
    "    let printed = os.output(cmd);\n"
    "    let rc = os.lastStatus();\n"
    "    var message = strings.trim(fs.read(errFile));\n"
    "    var status = 0;\n"
    "    if strings.isInt(strings.trim(printed)) {\n"
    "        status = strings.toInt(strings.trim(printed));\n"
    "    }\n"
    "    if rc != 0 && strings.isEmpty(message) {\n"
    "        message = \"curl failed with status ${rc}\";\n"
    "        if rc == -1 || rc == 127 {\n"
    "            message = \"could not run curl\";\n"
    "        }\n"
    "    }\n"
    "    if rc == 0 {\n"
    "        message = \"\";\n"
    "    }\n"
    "    let response = Response {\n"
    "        status: status,\n"
    "        body: fs.read(bodyFile),\n"
    "        headers: parseHeaders(fs.read(headerFile)),\n"
    "        error: message,\n"
    "    };\n"
    "    fs.remove(headerFile);\n"
    "    fs.remove(bodyFile);\n"
    "    fs.remove(errFile);\n"
    "    fs.remove(sendFile);\n"
    "    return response;\n"
    "}\n"
    "\n"
    "func get(url: str): Response {\n"
    "    return request(\"GET\", url, \"\", noHeaders());\n"
    "}\n"
    "\n"
    "func delete(url: str): Response {\n"
    "    return request(\"DELETE\", url, \"\", noHeaders());\n"
    "}\n"
    "\n"
    "func post(url: str, body: str): Response {\n"
    "    return request(\"POST\", url, body, noHeaders());\n"
    "}\n"
    "\n"
    "func put(url: str, body: str): Response {\n"
    "    return request(\"PUT\", url, body, noHeaders());\n"
    "}\n"
    "\n"
    "// POSTs `body` with a `Content-Type` of application/json.\n"
    "func postJson(url: str, body: str): Response {\n"
    "    var h: {str: str} = {};\n"
    "    h[\"Content-Type\"] = \"application/json\";\n"
    "    return request(\"POST\", url, body, h);\n"
    "}\n"
    "\n"
    "// Saves a URL's body to `path`. False if it failed or the status was not 2xx.\n"
    "func download(url: str, path: str): bool {\n"
    "    let r = get(url);\n"
    "    if !ok(r) {\n"
    "        return false;\n"
    "    }\n"
    "    return fs.write(path, r.body);\n"
    "}\n"
    "\n";

static const char src_ansi[] =
    "// The `ansi` module: colors and styles for terminals, as escape sequences.\n"
    "//\n"
    "//     print(ansi.red(\"error\") + \": \" + ansi.bold(message));\n"
    "//\n"
    "// Each function wraps its text so the style ends where the text does. Pair\n"
    "// with `ansi.enabled(os.hasEnv(\"NO_COLOR\"))`-style checks of your own when\n"
    "// output may go to a file; the functions always emit codes.\n"
    "\n"
    "import strings;\n"
    "\n"
    "func esc(): str {\n"
    "    return strings.fromCode(27);\n"
    "}\n"
    "\n"
    "func code(n: int, text: str): str {\n"
    "    return esc() + \"[\" + strings.fromInt(n) + \"m\" + text + esc() + \"[0m\";\n"
    "}\n"
    "\n"
    "func bold(text: str): str { return code(1, text); }\n"
    "func dim(text: str): str { return code(2, text); }\n"
    "func italic(text: str): str { return code(3, text); }\n"
    "func underline(text: str): str { return code(4, text); }\n"
    "\n"
    "func black(text: str): str { return code(30, text); }\n"
    "func red(text: str): str { return code(31, text); }\n"
    "func green(text: str): str { return code(32, text); }\n"
    "func yellow(text: str): str { return code(33, text); }\n"
    "func blue(text: str): str { return code(34, text); }\n"
    "func magenta(text: str): str { return code(35, text); }\n"
    "func cyan(text: str): str { return code(36, text); }\n"
    "func white(text: str): str { return code(37, text); }\n"
    "func gray(text: str): str { return code(90, text); }\n"
    "\n"
    "// 256-color foreground and background, `n` from 0 to 255.\n"
    "func color256(n: int, text: str): str {\n"
    "    return esc() + \"[38;5;\" + strings.fromInt(n) + \"m\" + text + esc() + \"[0m\";\n"
    "}\n"
    "\n"
    "func bg256(n: int, text: str): str {\n"
    "    return esc() + \"[48;5;\" + strings.fromInt(n) + \"m\" + text + esc() + \"[0m\";\n"
    "}\n"
    "\n"
    "func rgb(r: int, g: int, b: int, text: str): str {\n"
    "    return esc() + \"[38;2;\" + strings.fromInt(r) + \";\" + strings.fromInt(g) + \";\" + strings.fromInt(b) + \"m\" + text + esc() + \"[0m\";\n"
    "}\n"
    "\n"
    "// `text` without any escape sequences, for measuring or writing to a file.\n"
    "func strip(text: str): str {\n"
    "    var out: [str] = [];\n"
    "    let cs = strings.chars(text);\n"
    "    var i = 0;\n"
    "    while i < len(cs) {\n"
    "        if cs[i] == esc() && i + 1 < len(cs) && cs[i + 1] == \"[\" {\n"
    "            i += 2;\n"
    "            while i < len(cs) && !strings.contains(\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz\", cs[i]) {\n"
    "                i += 1;\n"
    "            }\n"
    "            i += 1;\n"
    "        } else {\n"
    "            push(out, cs[i]);\n"
    "            i += 1;\n"
    "        }\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "func clearScreen(): str {\n"
    "    return esc() + \"[2J\" + esc() + \"[H\";\n"
    "}\n"
    "\n";

static const char src_text[] =
    "// The `text` module: laying out and filling in text.\n"
    "//\n"
    "//     text.format(\"hello {name}, you are {age}\", values)\n"
    "//     text.center(\"title\", 20, \"=\")\n"
    "//     text.wrap(paragraph, 72)\n"
    "\n"
    "import strings;\n"
    "\n"
    "// Centers `s` in `width` characters, padding with `fill` (one character);\n"
    "// the extra one goes on the right when the padding is odd.\n"
    "func center(s: str, width: int, fill: str): str {\n"
    "    let total = width - len(s);\n"
    "    if total <= 0 {\n"
    "        return s;\n"
    "    }\n"
    "    let left = total / 2;\n"
    "    return strings.repeat(fill, left) + s + strings.repeat(fill, total - left);\n"
    "}\n"
    "\n"
    "// Replaces each `{key}` in `template` with the value for `key`. A key with no\n"
    "// value is left as written, and `{{` and `}}` give literal braces.\n"
    "func format(template: str, values: {str: str}): str {\n"
    "    var out: [str] = [];\n"
    "    let cs = strings.chars(template);\n"
    "    var i = 0;\n"
    "    while i < len(cs) {\n"
    "        let c = cs[i];\n"
    "        if c == \"{\" && i + 1 < len(cs) && cs[i + 1] == \"{\" {\n"
    "            push(out, \"{\");\n"
    "            i += 2;\n"
    "        } else if c == \"}\" && i + 1 < len(cs) && cs[i + 1] == \"}\" {\n"
    "            push(out, \"}\");\n"
    "            i += 2;\n"
    "        } else if c == \"{\" {\n"
    "            var j = i + 1;\n"
    "            while j < len(cs) && cs[j] != \"}\" && cs[j] != \"{\" {\n"
    "                j += 1;\n"
    "            }\n"
    "            if j < len(cs) && cs[j] == \"}\" {\n"
    "                let key = strings.join(cs[i + 1:j], \"\");\n"
    "                if contains(values, key) {\n"
    "                    push(out, values[key]);\n"
    "                } else {\n"
    "                    push(out, \"{\" + key + \"}\");\n"
    "                }\n"
    "                i = j + 1;\n"
    "            } else {\n"
    "                push(out, c);\n"
    "                i += 1;\n"
    "            }\n"
    "        } else {\n"
    "            push(out, c);\n"
    "            i += 1;\n"
    "        }\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "// Breaks `s` into lines of at most `width` characters at spaces. A word\n"
    "// longer than `width` gets a line of its own. Existing newlines are kept.\n"
    "func wrap(s: str, width: int): str {\n"
    "    var lines: [str] = [];\n"
    "    for para in strings.split(s, \"\\n\") {\n"
    "        var current = \"\";\n"
    "        for word in strings.split(para, \" \") {\n"
    "            if strings.isEmpty(word) {\n"
    "                continue;\n"
    "            }\n"
    "            if strings.isEmpty(current) {\n"
    "                current = word;\n"
    "            } else if len(current) + 1 + len(word) <= width {\n"
    "                current = current + \" \" + word;\n"
    "            } else {\n"
    "                push(lines, current);\n"
    "                current = word;\n"
    "            }\n"
    "        }\n"
    "        push(lines, current);\n"
    "    }\n"
    "    return strings.join(lines, \"\\n\");\n"
    "}\n"
    "\n"
    "// Puts `prefix` at the start of every line.\n"
    "func indent(s: str, prefix: str): str {\n"
    "    var out: [str] = [];\n"
    "    for line in strings.split(s, \"\\n\") {\n"
    "        if strings.isEmpty(line) {\n"
    "            push(out, line);\n"
    "        } else {\n"
    "            push(out, prefix + line);\n"
    "        }\n"
    "    }\n"
    "    return strings.join(out, \"\\n\");\n"
    "}\n"
    "\n"
    "// The text at least `width` characters wide, aligned left, right or centered.\n"
    "func alignLeft(s: str, width: int): str {\n"
    "    return strings.padRight(s, width, \" \");\n"
    "}\n"
    "\n"
    "func alignRight(s: str, width: int): str {\n"
    "    return strings.padLeft(s, width, \" \");\n"
    "}\n"
    "\n";

static const char src_toml[] =
    "// The `toml` module: reads TOML configuration files into a `json.Json` value.\n"
    "//\n"
    "//     switch toml.parse(fs.read(\"solis.toml\")) {\n"
    "//         case Success(cfg): print(json.getStr(cfg, \"name\", \"?\"));\n"
    "//         case Failure(msg): print(msg);\n"
    "//     }\n"
    "//\n"
    "// The result is the same `Json` tree the `json` module uses, so `json.get`,\n"
    "// `json.getInt` and `json.pretty` all apply, and a TOML file can be turned\n"
    "// into JSON text by printing it. Tables become objects, arrays of tables\n"
    "// become arrays of objects, integers and floats are both numbers, and dates\n"
    "// and times come through as their text. Supported: comments, `[table]` and\n"
    "// `[[array]]` headers, dotted keys, basic, literal and multi-line strings,\n"
    "// numbers with `_` and `0x`/`0o`/`0b` forms, `inf` and `nan`, arrays that\n"
    "// span lines, and inline tables.\n"
    "\n"
    "import json;\n"
    "import result;\n"
    "import strings;\n"
    "import math;\n"
    "\n"
    "struct Reader {\n"
    "    chars: [str];\n"
    "    pos: int;\n"
    "    error: str;\n"
    "}\n"
    "\n"
    "func fail(r: Reader, message: str) {\n"
    "    if !strings.isEmpty(r.error) {\n"
    "        return;\n"
    "    }\n"
    "    var line = 1;\n"
    "    var i = 0;\n"
    "    while i < r.pos && i < len(r.chars) {\n"
    "        if r.chars[i] == \"\\n\" {\n"
    "            line += 1;\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    r.error = \"line ${line}: ${message}\";\n"
    "}\n"
    "\n"
    "func peek(r: Reader): str {\n"
    "    if r.pos >= len(r.chars) {\n"
    "        return \"\";\n"
    "    }\n"
    "    return r.chars[r.pos];\n"
    "}\n"
    "\n"
    "func peekAt(r: Reader, offset: int): str {\n"
    "    if r.pos + offset >= len(r.chars) {\n"
    "        return \"\";\n"
    "    }\n"
    "    return r.chars[r.pos + offset];\n"
    "}\n"
    "\n"
    "func failed(r: Reader): bool {\n"
    "    return !strings.isEmpty(r.error);\n"
    "}\n"
    "\n"
    "// Spaces and tabs only.\n"
    "func skipBlanks(r: Reader) {\n"
    "    while peek(r) == \" \" || peek(r) == \"\\t\" {\n"
    "        r.pos += 1;\n"
    "    }\n"
    "}\n"
    "\n"
    "func skipComment(r: Reader) {\n"
    "    if peek(r) == \"#\" {\n"
    "        while r.pos < len(r.chars) && peek(r) != \"\\n\" {\n"
    "            r.pos += 1;\n"
    "        }\n"
    "    }\n"
    "}\n"
    "\n"
    "// Blanks, comments and newlines, for places where a value may continue on\n"
    "// the next line (inside arrays and inline tables across lines).\n"
    "func skipSpace(r: Reader) {\n"
    "    while r.pos < len(r.chars) {\n"
    "        let c = peek(r);\n"
    "        if c == \" \" || c == \"\\t\" || c == \"\\n\" || c == \"\\r\" {\n"
    "            r.pos += 1;\n"
    "        } else if c == \"#\" {\n"
    "            skipComment(r);\n"
    "        } else {\n"
    "            return;\n"
    "        }\n"
    "    }\n"
    "}\n"
    "\n"
    "func isBare(c: str): bool {\n"
    "    return strings.len(c) == 1 && strings.contains(\"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-\", c);\n"
    "}\n"
    "\n"
    "func hexValue(c: str): int {\n"
    "    if strings.len(c) != 1 {\n"
    "        return -1;\n"
    "    }\n"
    "    return strings.indexOf(\"0123456789abcdef\", strings.lower(c));\n"
    "}\n"
    "\n"
    "func readHex(r: Reader, count: int): int {\n"
    "    var v = 0;\n"
    "    var i = 0;\n"
    "    while i < count {\n"
    "        let d = hexValue(peek(r));\n"
    "        if d < 0 {\n"
    "            fail(r, \"bad unicode escape\");\n"
    "            return 0;\n"
    "        }\n"
    "        v = v * 16 + d;\n"
    "        r.pos += 1;\n"
    "        i += 1;\n"
    "    }\n"
    "    return v;\n"
    "}\n"
    "\n"
    "// A string body after its opening quote. `quote` is `\"` or `'`; `multi` for\n"
    "// the triple-quoted forms.\n"
    "func parseStringBody(r: Reader, quote: str, multi: bool): str {\n"
    "    var out: [str] = [];\n"
    "    if multi && peek(r) == \"\\r\" && peekAt(r, 1) == \"\\n\" {\n"
    "        r.pos += 2;\n"
    "    } else if multi && peek(r) == \"\\n\" {\n"
    "        r.pos += 1;\n"
    "    }\n"
    "    while true {\n"
    "        if r.pos >= len(r.chars) {\n"
    "            fail(r, \"unterminated string\");\n"
    "            return \"\";\n"
    "        }\n"
    "        let c = peek(r);\n"
    "        if c == quote {\n"
    "            if !multi {\n"
    "                r.pos += 1;\n"
    "                return strings.join(out, \"\");\n"
    "            }\n"
    "            if peekAt(r, 1) == quote && peekAt(r, 2) == quote {\n"
    "                r.pos += 3;\n"
    "                // up to two more quotes can belong to the string\n"
    "                while peek(r) == quote && strings.len(quote) == 1 {\n"
    "                    push(out, quote);\n"
    "                    r.pos += 1;\n"
    "                    if len(out) > 100000000 {\n"
    "                        break;\n"
    "                    }\n"
    "                }\n"
    "                return strings.join(out, \"\");\n"
    "            }\n"
    "            push(out, c);\n"
    "            r.pos += 1;\n"
    "            continue;\n"
    "        }\n"
    "        if c == \"\\n\" && !multi {\n"
    "            fail(r, \"newline in string\");\n"
    "            return \"\";\n"
    "        }\n"
    "        if c != \"\\\\\" || quote == \"'\" {\n"
    "            push(out, c);\n"
    "            r.pos += 1;\n"
    "            continue;\n"
    "        }\n"
    "        r.pos += 1;\n"
    "        let e = peek(r);\n"
    "        r.pos += 1;\n"
    "        if e == \"n\" {\n"
    "            push(out, \"\\n\");\n"
    "        } else if e == \"t\" {\n"
    "            push(out, \"\\t\");\n"
    "        } else if e == \"r\" {\n"
    "            push(out, \"\\r\");\n"
    "        } else if e == \"b\" {\n"
    "            push(out, strings.fromCode(8));\n"
    "        } else if e == \"f\" {\n"
    "            push(out, strings.fromCode(12));\n"
    "        } else if e == \"e\" {\n"
    "            push(out, strings.fromCode(27));\n"
    "        } else if e == \"\\\"\" || e == \"\\\\\" {\n"
    "            push(out, e);\n"
    "        } else if e == \"u\" {\n"
    "            push(out, strings.fromCode(readHex(r, 4)));\n"
    "        } else if e == \"U\" {\n"
    "            push(out, strings.fromCode(readHex(r, 8)));\n"
    "        } else if multi && (e == \"\\n\" || e == \" \" || e == \"\\t\" || e == \"\\r\") {\n"
    "            // a backslash at the end of a line trims the newline and the\n"
    "            // blanks that follow\n"
    "            r.pos -= 1;\n"
    "            skipBlanks(r);\n"
    "            if peek(r) == \"\\r\" {\n"
    "                r.pos += 1;\n"
    "            }\n"
    "            if peek(r) != \"\\n\" {\n"
    "                fail(r, \"bad escape\");\n"
    "                return \"\";\n"
    "            }\n"
    "            while peek(r) == \"\\n\" || peek(r) == \" \" || peek(r) == \"\\t\" || peek(r) == \"\\r\" {\n"
    "                r.pos += 1;\n"
    "            }\n"
    "        } else {\n"
    "            fail(r, \"unknown escape\");\n"
    "            return \"\";\n"
    "        }\n"
    "        if failed(r) {\n"
    "            return \"\";\n"
    "        }\n"
    "    }\n"
    "    return \"\";\n"
    "}\n"
    "\n"
    "func parseString(r: Reader): str {\n"
    "    let q = peek(r);\n"
    "    if peekAt(r, 1) == q && peekAt(r, 2) == q {\n"
    "        r.pos += 3;\n"
    "        return parseStringBody(r, q, true);\n"
    "    }\n"
    "    r.pos += 1;\n"
    "    return parseStringBody(r, q, false);\n"
    "}\n"
    "\n"
    "// A key segment: bare or quoted.\n"
    "func parseKeyPart(r: Reader): str {\n"
    "    skipBlanks(r);\n"
    "    let c = peek(r);\n"
    "    if c == \"\\\"\" || c == \"'\" {\n"
    "        return parseString(r);\n"
    "    }\n"
    "    var out: [str] = [];\n"
    "    while isBare(peek(r)) {\n"
    "        push(out, peek(r));\n"
    "        r.pos += 1;\n"
    "    }\n"
    "    if len(out) == 0 {\n"
    "        fail(r, \"expected a key\");\n"
    "        return \"\";\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "func parseKeyPath(r: Reader): [str] {\n"
    "    var parts: [str] = [];\n"
    "    while true {\n"
    "        push(parts, parseKeyPart(r));\n"
    "        if failed(r) {\n"
    "            return parts;\n"
    "        }\n"
    "        skipBlanks(r);\n"
    "        if peek(r) == \".\" {\n"
    "            r.pos += 1;\n"
    "        } else {\n"
    "            return parts;\n"
    "        }\n"
    "    }\n"
    "    return parts;\n"
    "}\n"
    "\n"
    "// The text of a bare value: everything up to a delimiter.\n"
    "func scanToken(r: Reader): str {\n"
    "    var out: [str] = [];\n"
    "    while r.pos < len(r.chars) {\n"
    "        let c = peek(r);\n"
    "        if c == \",\" || c == \"]\" || c == \"}\" || c == \"\\n\" || c == \"\\r\" || c == \"#\" || c == \" \" || c == \"\\t\" {\n"
    "            break;\n"
    "        }\n"
    "        push(out, c);\n"
    "        r.pos += 1;\n"
    "    }\n"
    "    return strings.join(out, \"\");\n"
    "}\n"
    "\n"
    "func digitsOnly(s: str): bool {\n"
    "    if strings.isEmpty(s) {\n"
    "        return false;\n"
    "    }\n"
    "    for c in strings.chars(s) {\n"
    "        if !strings.contains(\"0123456789\", c) {\n"
    "            return false;\n"
    "        }\n"
    "    }\n"
    "    return true;\n"
    "}\n"
    "\n"
    "func parseRadix(s: str, radix: int, digits: str): int {\n"
    "    var v = 0;\n"
    "    for c in strings.chars(s) {\n"
    "        let d = strings.indexOf(digits, strings.lower(c));\n"
    "        if d < 0 || d >= radix {\n"
    "            return -1;\n"
    "        }\n"
    "        v = v * radix + d;\n"
    "    }\n"
    "    return v;\n"
    "}\n"
    "\n"
    "func looksLikeDate(t: str): bool {\n"
    "    return strings.len(t) >= 8 && (strings.at(t, 4) == \"-\" || strings.at(t, 2) == \":\") && digitsOnly(strings.sub(t, 0, 2));\n"
    "}\n"
    "\n"
    "func parseScalar(r: Reader): json.Json {\n"
    "    var token = scanToken(r);\n"
    "    if strings.isEmpty(token) {\n"
    "        fail(r, \"expected a value\");\n"
    "        return json.Json.Null;\n"
    "    }\n"
    "    if token == \"true\" {\n"
    "        return json.Json.Bool(true);\n"
    "    }\n"
    "    if token == \"false\" {\n"
    "        return json.Json.Bool(false);\n"
    "    }\n"
    "    // a date, possibly followed by a space and a time\n"
    "    if looksLikeDate(token) {\n"
    "        if peek(r) == \" \" && digitsOnly(peekAt(r, 1)) && digitsOnly(peekAt(r, 2)) && peekAt(r, 3) == \":\" {\n"
    "            r.pos += 1;\n"
    "            token = token + \" \" + scanToken(r);\n"
    "        }\n"
    "        return json.Json.Str(token);\n"
    "    }\n"
    "    var clean = strings.replace(token, \"_\", \"\");\n"
    "    var sign = 1.0;\n"
    "    var body = clean;\n"
    "    if strings.startsWith(clean, \"+\") {\n"
    "        body = strings.sub(clean, 1, strings.len(clean));\n"
    "    } else if strings.startsWith(clean, \"-\") {\n"
    "        sign = -1.0;\n"
    "        body = strings.sub(clean, 1, strings.len(clean));\n"
    "    }\n"
    "    if body == \"inf\" {\n"
    "        return json.Json.Num(sign * math.inf());\n"
    "    }\n"
    "    if body == \"nan\" {\n"
    "        return json.Json.Num(math.nan());\n"
    "    }\n"
    "    if strings.startsWith(body, \"0x\") && strings.len(body) > 2 {\n"
    "        let v = parseRadix(strings.sub(body, 2, strings.len(body)), 16, \"0123456789abcdef\");\n"
    "        if v >= 0 {\n"
    "            return json.Json.Num(sign * math.toFloat(v));\n"
    "        }\n"
    "    } else if strings.startsWith(body, \"0o\") && strings.len(body) > 2 {\n"
    "        let v = parseRadix(strings.sub(body, 2, strings.len(body)), 8, \"01234567\");\n"
    "        if v >= 0 {\n"
    "            return json.Json.Num(sign * math.toFloat(v));\n"
    "        }\n"
    "    } else if strings.startsWith(body, \"0b\") && strings.len(body) > 2 {\n"
    "        let v = parseRadix(strings.sub(body, 2, strings.len(body)), 2, \"01\");\n"
    "        if v >= 0 {\n"
    "            return json.Json.Num(sign * math.toFloat(v));\n"
    "        }\n"
    "    } else if strings.isFloat(body) && strings.len(body) > 0 && strings.contains(\"0123456789\", strings.at(body, 0)) {\n"
    "        return json.Json.Num(sign * strings.toFloat(body));\n"
    "    }\n"
    "    fail(r, \"cannot read `${token}` as a value\");\n"
    "    return json.Json.Null;\n"
    "}\n"
    "\n"
    "func parseArray(r: Reader): json.Json {\n"
    "    r.pos += 1;\n"
    "    var items: [json.Json] = [];\n"
    "    while true {\n"
    "        skipSpace(r);\n"
    "        if peek(r) == \"]\" {\n"
    "            r.pos += 1;\n"
    "            return json.Json.Arr(items);\n"
    "        }\n"
    "        push(items, parseValue(r));\n"
    "        if failed(r) {\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "        skipSpace(r);\n"
    "        if peek(r) == \",\" {\n"
    "            r.pos += 1;\n"
    "        } else if peek(r) != \"]\" {\n"
    "            fail(r, \"expected `,` or `]` in array\");\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "    }\n"
    "    return json.Json.Null;\n"
    "}\n"
    "\n"
    "// The map at `path` below `table`, creating tables on the way. An array of\n"
    "// tables is entered at its last element. Sets an error on a clash.\n"
    "func descend(r: Reader, table: {str: json.Json}, path: [str]): {str: json.Json} {\n"
    "    var cur = table;\n"
    "    for name in path {\n"
    "        if contains(cur, name) {\n"
    "            switch cur[name] {\n"
    "                case Obj(fields): cur = fields;\n"
    "                case Arr(items): {\n"
    "                    if len(items) == 0 {\n"
    "                        fail(r, \"`${name}` is not a table\");\n"
    "                        return cur;\n"
    "                    }\n"
    "                    switch items[len(items) - 1] {\n"
    "                        case Obj(fields): cur = fields;\n"
    "                        case Null: fail(r, \"`${name}` is not a table\");\n"
    "                        case Bool(b): fail(r, \"`${name}` is not a table\");\n"
    "                        case Num(n): fail(r, \"`${name}` is not a table\");\n"
    "                        case Str(s): fail(r, \"`${name}` is not a table\");\n"
    "                        case Arr(inner): fail(r, \"`${name}` is not a table\");\n"
    "                    }\n"
    "                }\n"
    "                case Null: fail(r, \"`${name}` is not a table\");\n"
    "                case Bool(b): fail(r, \"`${name}` is not a table\");\n"
    "                case Num(n): fail(r, \"`${name}` is not a table\");\n"
    "                case Str(s): fail(r, \"`${name}` is not a table\");\n"
    "            }\n"
    "            if failed(r) {\n"
    "                return cur;\n"
    "            }\n"
    "        } else {\n"
    "            var fresh: {str: json.Json} = {};\n"
    "            cur[name] = json.Json.Obj(fresh);\n"
    "            cur = fresh;\n"
    "        }\n"
    "    }\n"
    "    return cur;\n"
    "}\n"
    "\n"
    "// `key = value` pairs into `table`.\n"
    "func assign(r: Reader, table: {str: json.Json}, path: [str], value: json.Json) {\n"
    "    let parent = descend(r, table, path[:len(path) - 1]);\n"
    "    if failed(r) {\n"
    "        return;\n"
    "    }\n"
    "    let last = path[len(path) - 1];\n"
    "    if contains(parent, last) {\n"
    "        fail(r, \"key `${last}` is defined twice\");\n"
    "        return;\n"
    "    }\n"
    "    parent[last] = value;\n"
    "}\n"
    "\n"
    "func parseInlineTable(r: Reader): json.Json {\n"
    "    r.pos += 1;\n"
    "    var fields: {str: json.Json} = {};\n"
    "    skipSpace(r);\n"
    "    if peek(r) == \"}\" {\n"
    "        r.pos += 1;\n"
    "        return json.Json.Obj(fields);\n"
    "    }\n"
    "    while true {\n"
    "        skipSpace(r);\n"
    "        let path = parseKeyPath(r);\n"
    "        if failed(r) {\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "        skipBlanks(r);\n"
    "        if peek(r) != \"=\" {\n"
    "            fail(r, \"expected `=`\");\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "        r.pos += 1;\n"
    "        let value = parseValue(r);\n"
    "        if failed(r) {\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "        assign(r, fields, path, value);\n"
    "        if failed(r) {\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "        skipSpace(r);\n"
    "        if peek(r) == \",\" {\n"
    "            r.pos += 1;\n"
    "        } else if peek(r) == \"}\" {\n"
    "            r.pos += 1;\n"
    "            return json.Json.Obj(fields);\n"
    "        } else {\n"
    "            fail(r, \"expected `,` or `}` in inline table\");\n"
    "            return json.Json.Null;\n"
    "        }\n"
    "    }\n"
    "    return json.Json.Null;\n"
    "}\n"
    "\n"
    "func parseValue(r: Reader): json.Json {\n"
    "    skipBlanks(r);\n"
    "    let c = peek(r);\n"
    "    if c == \"\\\"\" || c == \"'\" {\n"
    "        let s = parseString(r);\n"
    "        return json.Json.Str(s);\n"
    "    }\n"
    "    if c == \"[\" {\n"
    "        return parseArray(r);\n"
    "    }\n"
    "    if c == \"{\" {\n"
    "        return parseInlineTable(r);\n"
    "    }\n"
    "    return parseScalar(r);\n"
    "}\n"
    "\n"
    "// Reads the rest of a line after a value or header: blanks, a comment, then\n"
    "// a newline or the end.\n"
    "func endOfLine(r: Reader) {\n"
    "    skipBlanks(r);\n"
    "    skipComment(r);\n"
    "    if peek(r) == \"\\r\" {\n"
    "        r.pos += 1;\n"
    "    }\n"
    "    if r.pos < len(r.chars) && peek(r) != \"\\n\" {\n"
    "        fail(r, \"unexpected `${peek(r)}`\");\n"
    "        return;\n"
    "    }\n"
    "    r.pos += 1;\n"
    "}\n"
    "\n"
    "// One document into a tree. Errors name the line.\n"
    "func parse(text: str): result.Result[json.Json, str] {\n"
    "    let r = Reader { chars: strings.chars(text), pos: 0, error: \"\" };\n"
    "    var root: {str: json.Json} = {};\n"
    "    var current = root;\n"
    "    while r.pos < len(r.chars) && !failed(r) {\n"
    "        skipSpace(r);\n"
    "        if r.pos >= len(r.chars) {\n"
    "            break;\n"
    "        }\n"
    "        if peek(r) == \"[\" {\n"
    "            let isArray = peekAt(r, 1) == \"[\";\n"
    "            if isArray {\n"
    "                r.pos += 2;\n"
    "            } else {\n"
    "                r.pos += 1;\n"
    "            }\n"
    "            let path = parseKeyPath(r);\n"
    "            if failed(r) {\n"
    "                break;\n"
    "            }\n"
    "            skipBlanks(r);\n"
    "            if peek(r) != \"]\" || (isArray && peekAt(r, 1) != \"]\") {\n"
    "                fail(r, \"unterminated table header\");\n"
    "                break;\n"
    "            }\n"
    "            if isArray {\n"
    "                r.pos += 2;\n"
    "            } else {\n"
    "                r.pos += 1;\n"
    "            }\n"
    "            if isArray {\n"
    "                let parent = descend(r, root, path[:len(path) - 1]);\n"
    "                if failed(r) {\n"
    "                    break;\n"
    "                }\n"
    "                let last = path[len(path) - 1];\n"
    "                var fresh: {str: json.Json} = {};\n"
    "                if contains(parent, last) {\n"
    "                    switch parent[last] {\n"
    "                        case Arr(items): push(items, json.Json.Obj(fresh));\n"
    "                        case Null: fail(r, \"`${last}` is not an array of tables\");\n"
    "                        case Bool(b): fail(r, \"`${last}` is not an array of tables\");\n"
    "                        case Num(n): fail(r, \"`${last}` is not an array of tables\");\n"
    "                        case Str(s): fail(r, \"`${last}` is not an array of tables\");\n"
    "                        case Obj(fields): fail(r, \"`${last}` is not an array of tables\");\n"
    "                    }\n"
    "                } else {\n"
    "                    var items: [json.Json] = [];\n"
    "                    push(items, json.Json.Obj(fresh));\n"
    "                    parent[last] = json.Json.Arr(items);\n"
    "                }\n"
    "                current = fresh;\n"
    "            } else {\n"
    "                current = descend(r, root, path);\n"
    "            }\n"
    "            if !failed(r) {\n"
    "                endOfLine(r);\n"
    "            }\n"
    "            continue;\n"
    "        }\n"
    "        let path = parseKeyPath(r);\n"
    "        if failed(r) {\n"
    "            break;\n"
    "        }\n"
    "        skipBlanks(r);\n"
    "        if peek(r) != \"=\" {\n"
    "            fail(r, \"expected `=` after the key\");\n"
    "            break;\n"
    "        }\n"
    "        r.pos += 1;\n"
    "        let value = parseValue(r);\n"
    "        if failed(r) {\n"
    "            break;\n"
    "        }\n"
    "        assign(r, current, path, value);\n"
    "        if !failed(r) {\n"
    "            endOfLine(r);\n"
    "        }\n"
    "    }\n"
    "    if failed(r) {\n"
    "        let bad: result.Result[json.Json, str] = result.Result.Failure(r.error);\n"
    "        return bad;\n"
    "    }\n"
    "    let good: result.Result[json.Json, str] = result.Result.Success(json.Json.Obj(root));\n"
    "    return good;\n"
    "}\n"
    "\n";

static const char src_net[] =
    "// The `net` module: TCP and UDP sockets.\n"
    "//\n"
    "// A socket is an int handle: 1 or more when it works, -1 when it failed, and\n"
    "// then `lastError()` says why. Handles are only meaningful to this module.\n"
    "// Everything blocks; use the timeout parameters (or `setTimeout`) to bound\n"
    "// the wait. Text is read and written as raw bytes, so any string can be sent.\n"
    "//\n"
    "//     let server = net.listen(\"127.0.0.1\", 8080);\n"
    "//     let conn = net.accept(server, -1);\n"
    "//     let request = net.read(conn, 4096);\n"
    "//     net.write(conn, \"HTTP/1.0 200 OK\\r\\n\\r\\nhi\");\n"
    "//     net.close(conn);\n"
    "//\n"
    "// Only the standard interpreter opens this, and it is unavailable in the web\n"
    "// build (`isAvailable()` is false there).\n"
    "\n"
    "import strings;\n"
    "\n"
    "extern func isAvailable(): bool;\n"
    "\n"
    "// Starts listening. An empty host means every interface; port 0 picks a free\n"
    "// one, which `port` then reports.\n"
    "extern func listen(host: str, port: int): int;\n"
    "\n"
    "// Waits up to `timeoutMs` for a client (negative: forever) and returns its\n"
    "// connection, or -1 on timeout (`lastError()` is \"timeout\") or failure.\n"
    "extern func accept(server: int, timeoutMs: int): int;\n"
    "\n"
    "extern func connect(host: str, port: int): int;\n"
    "\n"
    "// Up to `max` bytes, as soon as some arrive. \"\" means the other side closed\n"
    "// (`lastError()` is \"closed\"), the timeout passed (\"timeout\"), or an error.\n"
    "extern func read(conn: int, max: int): str;\n"
    "\n"
    "// Sends everything; returns the byte count, or -1.\n"
    "extern func write(conn: int, data: str): int;\n"
    "\n"
    "// Milliseconds a read or write may wait on a connection or UDP socket;\n"
    "// 0 waits forever.\n"
    "extern func setTimeout(sock: int, ms: int): bool;\n"
    "\n"
    "// A UDP socket bound to `host:port`.\n"
    "extern func udp(host: str, port: int): int;\n"
    "extern func sendTo(sock: int, host: str, port: int, data: str): int;\n"
    "\n"
    "// One datagram, \"\" on timeout or error. `peer(0)` is the sender afterwards.\n"
    "extern func recvFrom(sock: int, max: int): str;\n"
    "\n"
    "extern func close(sock: int);\n"
    "\n"
    "// The local port of a listener, connection or UDP socket, or -1.\n"
    "extern func port(sock: int): int;\n"
    "\n"
    "// \"ip:port\" of the remote end of a connection. `peer(0)` is the address of\n"
    "// the last client accepted or datagram received.\n"
    "extern func peer(sock: int): str;\n"
    "\n"
    "// The first IP address a host name resolves to, or \"\".\n"
    "extern func resolve(host: str): str;\n"
    "\n"
    "extern func lastError(): str;\n"
    "\n"
    "// Reads until `marker` has been seen or the connection ends, then returns\n"
    "// everything read, which can include bytes after the marker.\n"
    "func readUntil(conn: int, marker: str, limit: int): str {\n"
    "    var got = \"\";\n"
    "    while strings.byteLen(got) < limit && !strings.contains(got, marker) {\n"
    "        let chunk = read(conn, 4096);\n"
    "        if strings.isEmpty(chunk) {\n"
    "            return got;\n"
    "        }\n"
    "        got = got + chunk;\n"
    "    }\n"
    "    return got;\n"
    "}\n"
    "\n"
    "// Reads exactly `count` bytes, or fewer if the connection ends first.\n"
    "func readBytes(conn: int, count: int): str {\n"
    "    var got = \"\";\n"
    "    var have = 0;\n"
    "    while have < count {\n"
    "        let chunk = read(conn, count - have);\n"
    "        if strings.isEmpty(chunk) {\n"
    "            return got;\n"
    "        }\n"
    "        got = got + chunk;\n"
    "        have += strings.byteLen(chunk);\n"
    "    }\n"
    "    return got;\n"
    "}\n"
    "\n";

static const char src_sqlite[] =
    "// The `sqlite` module: SQLite databases.\n"
    "//\n"
    "//     let db = sqlite.open(\"app.db\");\n"
    "//     sqlite.exec(db, \"create table if not exists users (id integer primary key, name text)\", []);\n"
    "//     sqlite.exec(db, \"insert into users (name) values (?)\", [\"Ada\"]);\n"
    "//     for row in sqlite.records(db, \"select id, name from users where name = ?\", [\"Ada\"]) {\n"
    "//         print(\"${row[\"id\"]} ${row[\"name\"]}\");\n"
    "//     }\n"
    "//     sqlite.close(db);\n"
    "//\n"
    "// The SQLite library is loaded from the system when first needed (libsqlite3\n"
    "// on Linux and macOS, sqlite3.dll on Windows), so Solis itself has no\n"
    "// dependency on it; `available()` tells whether it was found. Open a file\n"
    "// path, or \":memory:\" for a database that lives as long as the handle.\n"
    "//\n"
    "// Parameters are passed as text in the `?` slots and SQLite converts them by\n"
    "// the column's type, so `[\"42\"]` fills an integer column. Results come back\n"
    "// as text too: numbers print the way SQLite prints them, and NULL is \"\".\n"
    "// Use `strings.toInt` and `toFloat` on what you read. A failed call returns\n"
    "// -1 (or an empty result) and `error()` gives the message.\n"
    "//\n"
    "// Only the standard interpreter opens this.\n"
    "\n"
    "extern func available(): bool;\n"
    "\n"
    "// The SQLite library's version, or \"\" if it is not available.\n"
    "extern func version(): str;\n"
    "\n"
    "// A handle to use with the other functions, or -1 (see `error`).\n"
    "extern func open(path: str): int;\n"
    "extern func close(db: int);\n"
    "\n"
    "// Runs one or more statements. Parameters apply to the first. Returns the\n"
    "// number of rows changed, or -1 on an error.\n"
    "extern func exec(db: int, sql: str, params: [str]): int;\n"
    "\n"
    "// Runs the first statement and returns its rows as text. The first row holds\n"
    "// the column names. An error gives an empty array.\n"
    "extern func query(db: int, sql: str, params: [str]): [[str]];\n"
    "\n"
    "// The rowid of the last insert.\n"
    "extern func lastInsertId(db: int): int;\n"
    "\n"
    "extern func error(): str;\n"
    "\n"
    "// Each result row as a map from column name to value.\n"
    "func records(db: int, sql: str, params: [str]): [{str: str}] {\n"
    "    let rows = query(db, sql, params);\n"
    "    var out: [{str: str}] = [];\n"
    "    if len(rows) == 0 {\n"
    "        return out;\n"
    "    }\n"
    "    let names = rows[0];\n"
    "    var r = 1;\n"
    "    while r < len(rows) {\n"
    "        var rec: {str: str} = {};\n"
    "        var c = 0;\n"
    "        while c < len(names) && c < len(rows[r]) {\n"
    "            rec[names[c]] = rows[r][c];\n"
    "            c += 1;\n"
    "        }\n"
    "        push(out, rec);\n"
    "        r += 1;\n"
    "    }\n"
    "    return out;\n"
    "}\n"
    "\n"
    "// The first cell of the first row, or `fallback` if there is none.\n"
    "func value(db: int, sql: str, params: [str], fallback: str): str {\n"
    "    let rows = query(db, sql, params);\n"
    "    if len(rows) < 2 || len(rows[1]) == 0 {\n"
    "        return fallback;\n"
    "    }\n"
    "    return rows[1][0];\n"
    "}\n"
    "\n"
    "// Runs `sql` with no parameters.\n"
    "func run(db: int, sql: str): int {\n"
    "    var none: [str] = [];\n"
    "    return exec(db, sql, none);\n"
    "}\n"
    "\n";

static const char src_httpd[] =
    "// The `httpd` module: a small HTTP/1.1 server, one request at a time.\n"
    "//\n"
    "//     let server = httpd.listen(\"127.0.0.1\", 8080);\n"
    "//     while true {\n"
    "//         let req = httpd.next(server);\n"
    "//         if !req.ok { continue; }\n"
    "//         if req.path == \"/\" {\n"
    "//             httpd.text(req, 200, \"hello\");\n"
    "//         } else {\n"
    "//             httpd.text(req, 404, \"not found\");\n"
    "//         }\n"
    "//     }\n"
    "//\n"
    "// `next` waits for a client, reads its request, and returns it; you answer\n"
    "// with one of the `respond` functions, which also close the connection. It\n"
    "// handles one connection at a time and does not keep connections alive, which\n"
    "// suits tools, webhooks and local services rather than public traffic. There\n"
    "// is no TLS; put a reverse proxy in front for HTTPS. Built on `net`.\n"
    "\n"
    "import net;\n"
    "import strings;\n"
    "\n"
    "struct Request {\n"
    "    ok: bool;                  // false when the client sent something unusable; just call `next` again\n"
    "    method: str;               // \"GET\", \"POST\", ...\n"
    "    path: str;                 // \"/a/b\", without the query\n"
    "    query: str;                // after the `?`, undecoded; see `url.parseQuery`\n"
    "    headers: {str: str};       // names in lower case\n"
    "    body: str;\n"
    "    peer: str;                 // the client's \"ip:port\"\n"
    "    conn: int;                 // pass the request itself to `respond`\n"
    "}\n"
    "\n"
    "// The most header bytes and body bytes accepted.\n"
    "var maxHeader = 65536;\n"
    "var maxBody = 10485760;\n"
    "\n"
    "func listen(host: str, port: int): int {\n"
    "    return net.listen(host, port);\n"
    "}\n"
    "\n"
    "func stop(server: int) {\n"
    "    net.close(server);\n"
    "}\n"
    "\n"
    "func emptyHeaders(): {str: str} {\n"
    "    var h: {str: str} = {};\n"
    "    return h;\n"
    "}\n"
    "\n"
    "func badRequest(conn: int): Request {\n"
    "    return Request { ok: false, method: \"\", path: \"\", query: \"\", headers: emptyHeaders(), body: \"\", peer: \"\", conn: conn };\n"
    "}\n"
    "\n"
    "// Waits for the next client (forever) and reads its request. A client that\n"
    "// connects and sends nothing for ten seconds, or sends garbage, gives a\n"
    "// request with `ok` false after a 400 response.\n"
    "func next(server: int): Request {\n"
    "    let conn = net.accept(server, -1);\n"
    "    if conn < 0 {\n"
    "        return badRequest(-1);\n"
    "    }\n"
    "    return read(conn);\n"
    "}\n"
    "\n"
    "// Like `next` but gives up after `ms` milliseconds with `ok` false and `conn` -1.\n"
    "func nextWithin(server: int, ms: int): Request {\n"
    "    let conn = net.accept(server, ms);\n"
    "    if conn < 0 {\n"
    "        return badRequest(-1);\n"
    "    }\n"
    "    return read(conn);\n"
    "}\n"
    "\n"
    "func read(conn: int): Request {\n"
    "    net.setTimeout(conn, 10000);\n"
    "    let peer = net.peer(conn);\n"
    "    let raw = net.readUntil(conn, \"\\r\\n\\r\\n\", maxHeader);\n"
    "    let split = strings.indexOf(raw, \"\\r\\n\\r\\n\");\n"
    "    if split < 0 {\n"
    "        net.write(conn, \"HTTP/1.1 400 Bad Request\\r\\nConnection: close\\r\\nContent-Length: 0\\r\\n\\r\\n\");\n"
    "        net.close(conn);\n"
    "        return badRequest(-1);\n"
    "    }\n"
    "    let head = strings.sub(raw, 0, split);\n"
    "    var body = strings.sub(raw, split + 4, strings.len(raw));\n"
    "    let lines = strings.split(head, \"\\r\\n\");\n"
    "    let first = strings.split(lines[0], \" \");\n"
    "    if len(first) < 2 {\n"
    "        net.write(conn, \"HTTP/1.1 400 Bad Request\\r\\nConnection: close\\r\\nContent-Length: 0\\r\\n\\r\\n\");\n"
    "        net.close(conn);\n"
    "        return badRequest(-1);\n"
    "    }\n"
    "    var headers = emptyHeaders();\n"
    "    var i = 1;\n"
    "    while i < len(lines) {\n"
    "        let colon = strings.indexOf(lines[i], \":\");\n"
    "        if colon > 0 {\n"
    "            headers[strings.lower(strings.sub(lines[i], 0, colon))] = strings.trim(strings.sub(lines[i], colon + 1, strings.len(lines[i])));\n"
    "        }\n"
    "        i += 1;\n"
    "    }\n"
    "    // the body: Content-Length bytes, some of which may already be in `body`\n"
    "    var want = 0;\n"
    "    if contains(headers, \"content-length\") && strings.isInt(headers[\"content-length\"]) {\n"
    "        want = strings.toInt(headers[\"content-length\"]);\n"
    "    }\n"
    "    if want > maxBody {\n"
    "        net.write(conn, \"HTTP/1.1 413 Payload Too Large\\r\\nConnection: close\\r\\nContent-Length: 0\\r\\n\\r\\n\");\n"
    "        net.close(conn);\n"
    "        return badRequest(-1);\n"
    "    }\n"
    "    let have = strings.byteLen(body);\n"
    "    if have < want {\n"
    "        body = body + net.readBytes(conn, want - have);\n"
    "    }\n"
    "    var target = first[1];\n"
    "    var query = \"\";\n"
    "    let q = strings.indexOf(target, \"?\");\n"
    "    if q >= 0 {\n"
    "        query = strings.sub(target, q + 1, strings.len(target));\n"
    "        target = strings.sub(target, 0, q);\n"
    "    }\n"
    "    return Request { ok: true, method: first[0], path: target, query: query, headers: headers, body: body, peer: peer, conn: conn };\n"
    "}\n"
    "\n"
    "func statusText(status: int): str {\n"
    "    if status == 200 { return \"OK\"; }\n"
    "    if status == 201 { return \"Created\"; }\n"
    "    if status == 202 { return \"Accepted\"; }\n"
    "    if status == 204 { return \"No Content\"; }\n"
    "    if status == 301 { return \"Moved Permanently\"; }\n"
    "    if status == 302 { return \"Found\"; }\n"
    "    if status == 303 { return \"See Other\"; }\n"
    "    if status == 304 { return \"Not Modified\"; }\n"
    "    if status == 307 { return \"Temporary Redirect\"; }\n"
    "    if status == 400 { return \"Bad Request\"; }\n"
    "    if status == 401 { return \"Unauthorized\"; }\n"
    "    if status == 403 { return \"Forbidden\"; }\n"
    "    if status == 404 { return \"Not Found\"; }\n"
    "    if status == 405 { return \"Method Not Allowed\"; }\n"
    "    if status == 409 { return \"Conflict\"; }\n"
    "    if status == 413 { return \"Payload Too Large\"; }\n"
    "    if status == 415 { return \"Unsupported Media Type\"; }\n"
    "    if status == 422 { return \"Unprocessable Entity\"; }\n"
    "    if status == 429 { return \"Too Many Requests\"; }\n"
    "    if status == 500 { return \"Internal Server Error\"; }\n"
    "    if status == 501 { return \"Not Implemented\"; }\n"
    "    if status == 503 { return \"Service Unavailable\"; }\n"
    "    return \"Status\";\n"
    "}\n"
    "\n"
    "// Answers with extra headers (name to value) and closes the connection.\n"
    "func respondWith(req: Request, status: int, contentType: str, headers: {str: str}, body: str) {\n"
    "    var out = \"HTTP/1.1 \" + strings.fromInt(status) + \" \" + statusText(status) + \"\\r\\n\";\n"
    "    out = out + \"Content-Type: \" + contentType + \"\\r\\n\";\n"
    "    out = out + \"Content-Length: \" + strings.fromInt(strings.byteLen(body)) + \"\\r\\n\";\n"
    "    out = out + \"Connection: close\\r\\n\";\n"
    "    for name in keys(headers) {\n"
    "        out = out + name + \": \" + headers[name] + \"\\r\\n\";\n"
    "    }\n"
    "    out = out + \"\\r\\n\";\n"
    "    if req.method != \"HEAD\" {\n"
    "        out = out + body;\n"
    "    }\n"
    "    net.write(req.conn, out);\n"
    "    net.close(req.conn);\n"
    "}\n"
    "\n"
    "func respond(req: Request, status: int, contentType: str, body: str) {\n"
    "    respondWith(req, status, contentType, emptyHeaders(), body);\n"
    "}\n"
    "\n"
    "func text(req: Request, status: int, body: str) {\n"
    "    respond(req, status, \"text/plain; charset=utf-8\", body);\n"
    "}\n"
    "\n"
    "func html(req: Request, status: int, body: str) {\n"
    "    respond(req, status, \"text/html; charset=utf-8\", body);\n"
    "}\n"
    "\n"
    "// `body` is JSON text, for instance from `json.stringify`.\n"
    "func json(req: Request, status: int, body: str) {\n"
    "    respond(req, status, \"application/json\", body);\n"
    "}\n"
    "\n"
    "func redirect(req: Request, location: str) {\n"
    "    var h = emptyHeaders();\n"
    "    h[\"Location\"] = location;\n"
    "    respondWith(req, 302, \"text/plain; charset=utf-8\", h, \"\");\n"
    "}\n"
    "\n"
    "// The MIME type for a file name, by extension; application/octet-stream if\n"
    "// it is not one of the common ones.\n"
    "func mimeType(file: str): str {\n"
    "    let lower = strings.lower(file);\n"
    "    if strings.endsWith(lower, \".html\") || strings.endsWith(lower, \".htm\") { return \"text/html; charset=utf-8\"; }\n"
    "    if strings.endsWith(lower, \".css\") { return \"text/css; charset=utf-8\"; }\n"
    "    if strings.endsWith(lower, \".js\") || strings.endsWith(lower, \".mjs\") { return \"text/javascript; charset=utf-8\"; }\n"
    "    if strings.endsWith(lower, \".json\") { return \"application/json\"; }\n"
    "    if strings.endsWith(lower, \".txt\") || strings.endsWith(lower, \".md\") { return \"text/plain; charset=utf-8\"; }\n"
    "    if strings.endsWith(lower, \".svg\") { return \"image/svg+xml\"; }\n"
    "    if strings.endsWith(lower, \".png\") { return \"image/png\"; }\n"
    "    if strings.endsWith(lower, \".jpg\") || strings.endsWith(lower, \".jpeg\") { return \"image/jpeg\"; }\n"
    "    if strings.endsWith(lower, \".gif\") { return \"image/gif\"; }\n"
    "    if strings.endsWith(lower, \".ico\") { return \"image/x-icon\"; }\n"
    "    if strings.endsWith(lower, \".wasm\") { return \"application/wasm\"; }\n"
    "    if strings.endsWith(lower, \".xml\") { return \"application/xml\"; }\n"
    "    if strings.endsWith(lower, \".pdf\") { return \"application/pdf\"; }\n"
    "    return \"application/octet-stream\";\n"
    "}\n"
    "\n";
